insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('auf-mein-dochboon-liigt-so-vueue-gramuuri-i-kennd-an-floomoakd-aufmochn', 'Auf mein Dochboon liigt so vüü Gramuuri - I kennd an Floomoakd aufmochn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf meinem Dachboden liegt so viel Kramuri - ich könnt ''nen Flohmarkt aufmachen!', '[{"kategorie": "wörtlich", "text": "\"Auf meinem Dachboden liegt so viel Krimskrams herum – ich könnte glatt einen Flohmarkt aufmachen!\"  2. Ich hab so viel Plunder unterm Dach, dass ich jeden Sonntag was am Flohmarkt verkaufen könnte!  3. Mein Dachboden ist voll mit Gerümpel – das ganze Kleinzeug dort oben reicht für einen eigenen Stand auf dem Flohmarkt!"}]'::jsonb, ''),
  ('kropfn-boochn-is-nix-fia-grobmotorika-sunst-schwimmd-da-kropfn-davoo', 'Kropfn boochn is nix fia Grobmotorika - sunst schwimmd da Kropfn davoo!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Krapfen backen ist nichts für Grobmotoriker – sonst schwimmt der Krapfen davon!', '[{"kategorie": "wörtlich", "text": "\"Krapfen ausbacken ist nichts für Grobmotoriker – sonst taucht der Krapfen im Fett ab!\"  2. Wer Krapfen bäckt, braucht Fingerspitzengefühl – sonst geht der Krapfen im offenen Meer aus Fett unter!  3. Krapfen backen ist Feinarbeit – sonst gehen die Dinger auf Tauchstation!"}]'::jsonb, ''),
  ('ob-marmelade-indiana-oda-vanillikropfn-aum-end-laundns-olle-in-mein-bauch', 'Ob Marmelade-, Indiana- oda Vanillikropfn - aum End laundns olle in mein Bauch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ob Marmelade-, Indianer- oder Vanillekrapfen - am Ende landen sie alle in meinem Bauch!', '[{"kategorie": "wörtlich", "text": "\"Ob Marmelade-, Indianer- oder Vanillekrapfen - am Ende verschwinden sie doch alle in meinem Magen!\"  2. Ob Marmelade-, Indianer- oder Vanillekrapfen - am Ende treten sie alle ihre letzte Reise in meinen Bauch an!  3. Ob Marmelade-, Indianer- oder Vanillekrapfen - ich mach sie alle weg und lass sie genüsslich in meinen Futtersack wandern!"}]'::jsonb, ''),
  ('ob-marueuen-indiana-oda-vanillikropfn-aum-end-laundns-olle-in-mein-bauch', 'Ob Marüün-, Indiana- oda Vanillikropfn - aum End laundns olle in mein Bauch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ob Marillen-, Indianer- oder Vanillekrapfen - am Ende landen sie alle in meinem Bauch!', '[{"kategorie": "wörtlich", "text": "\"Ob Marillen-, Indianer- oder Vanillekrapfen - am Ende verschwinden sie doch alle in meinem Magen!\"  2. Ob Marillen-, Indianer- oder Vanillekrapfen - am Ende treten sie alle ihre letzte Reise in meinen Bauch an!  3. Ob Marillen-, Indianer- oder Vanillekrapfen - ich mach sie alle weg und lass sie genüsslich in meinen Futtersack wandern!"}]'::jsonb, ''),
  ('wea-bloosshapad-iwad-weidn-rennd-kennds-gfueue-von-woame-kuakropfn', 'Wea bloosshapad iwad Weidn rennd, kennds Gfüü von woame Kuakropfn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer bloßhapert über die Weide läuft, kennt das Gefühl von warmen Kuhkrapfen!', '[{"kategorie": "wörtlich", "text": "\"Wer barfuß über die Weide läuft, kennt das Gefühl von warmen Kuhfladen!\"  2. Barfuß über die Wiese? Dann weißt du, wie sich ein frischer Rinderfladen anfühlt!  3. Wer ohne Schuhe über die Weide geht, tritt garantiert mal in einen warmen Kuhfladen!"}]'::jsonb, ''),
  ('krapfal-boochn-is-nix-fia-grobmotorika-sunst-schwimmd-s-krapfal-davoo', 'Krapfal boochn is nix fia Grobmotorika - sunst schwimmd s''Krapfal davoo!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Krapferln backen ist nichts für Grobmotoriker – sonst schwimmt das Krapferl davon!', '[{"kategorie": "wörtlich", "text": "\"Krapferln ausbacken ist nichts für Grobmotoriker – sonst taucht das Krapferl im Fett ab!\"  2. Wer Krapferln bäckt, braucht Fingerspitzengefühl – sonst geht das Krapferl im offenen Meer aus Fett unter!  3. Krapferln backen ist Feinarbeit – sonst gehen die Dinger auf Tauchstation!"}]'::jsonb, ''),
  ('ea-schwaeamd-von-groosse-meloonan-und-valiabd-si-daunn-in-klaane-krapfaln', 'Ea schwäamd von groosse Meloonan - und valiabd si daunn in klaane Krapfaln!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er schwärmt von großen Melonen – und verliebt sich dann in kleine Krapferln!', '[{"kategorie": "wörtlich", "text": "\"Er redet immer von großen Titten – und verguckt sich dann in [[Eierspeistutteln]]!\"  2. Er träumt von zwei Kürbissen – und verliebt sich in zwei Marillen!  3. Er schwärmt von Doppel-D und verliebt sich dann in Mini-Titten!"}]'::jsonb, ''),
  ('a-braundtaachkrapfal-mochd-ned-dick-nua-glicklich', 'A Braundtaachkrapfal mochd ned dick - nua glicklich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Brandteigkrapferl macht nicht dick – nur glücklich!', '[{"kategorie": "wörtlich", "text": "\"Ein Brandteigkrapferl ist keine Kalorienbombe – sondern ein Seelentröster!\"  2. Der Brandteigkrapfen hat keine Kalorien – er hat Persönlichkeit!  3. Brandteigkrapferln sind kein Gebäck - das sind Glücksräder für die Seele!"}]'::jsonb, ''),
  ('a-punschkrapfal-is-wiara-roosa-gruass-aus-wean', 'A Punschkrapfal is wiara roosa Gruass aus Wean!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Punschkrapferl ist wie ein rosa Gruß aus Wien!', '[{"kategorie": "wörtlich", "text": "\"Das Punschkrapferl schmeckt wie ein kleiner rosa Liebesbrief aus Wien!\"  2. Das Punschkrapferl ist ein Stück Wien in verführerischem Zartrosa!  3. Ein Punschkrapferl ist ein rosa Würfel Glück, direkt aus Wien geschickt!"}]'::jsonb, ''),
  ('a-krapfal-liing-lossn', 'a Krapfal liing lossn', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Krapferl liegen lassen', '[{"kategorie": "wörtlich", "text": "\"ein Kothäufchen hinterlassen\""}, {"kategorie": "fig., scherzhaft für", "text": "sich vor Angst in die Hose machen"}, {"kategorie": "", "text": "vor lauter Angst die Hosen gestrichen voll haben"}]'::jsonb, 'Da deppade Hund vom Nochban hod schoo wiida direkt vua unsara Tia a Krapfal liing lossn!'),
  ('da-deppade-hund-vom-nochban-hod-schoo-wiida-direkt-vua-unsara-tia-a-krapfal-liing-lossn', 'Da deppade Hund vom Nochban hod schoo wiida direkt vua unsara Tia a Krapfal liing lossn!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Der depperte Hund vom Nachbarn hat schon wieder direkt vor unserer Tür ein Krapferl liegen lassen!', '[{"kategorie": "wörtlich", "text": "\"Der blöde Nachbarshund hat schon wieder direkt vor unserer Tür ein Kothäufchen hinterlassen!\"  2. Schon wieder hat der Nachbarshund direkt vor unserer Tür ein Häufchen gemacht!  3. Vor unserer Tür liegt schon wieder ein frischer Hundehaufen – natürlich von diesem blöden Nachbarshund!"}]'::jsonb, 'a Krapfal liing lossn'),
  ('wia-si-da-grissly-in-volla-laeng-vua-mia-aufgschdoeoed-hod-hob-i-a-krapfal-liing-lossn', 'Wia si da Grissly in volla Läng vua mia aufgschdööd hod, hob I a Krapfal liing lossn!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Als sich der Grizzlybär in voller Länge vor mir aufstellte, hab ich ein Krapferl liegen lassen!', '[{"kategorie": "wörtlich", "text": "\"Als sich der Grizzlybär in voller Länge vor mir aufstellte, hab ich mir vor lauter Angst in die Hose geschissen!\"  2. Als sich der Grizzly vor mir aufrichtete, hab ich vor Schreck die Hosen gestrichen voll gehabt!  3. Plötzlich stand der Grizzlybär hoch aufgerichtet vor mir – da hab ich mir vor Schiss fast die Hose vollgeballert!"}]'::jsonb, 'a Krapfal liing lossn'),
  ('sei-krapfal-ooleng', 'sei Krapfal ooleng', '', '', '', 'Wiener Sprüche, die sitzen!', 'sein Krapferl ablegen', '[{"kategorie": "wörtlich", "text": "\"sein Häufchen hinterlassen\""}, {"kategorie": "", "text": "\"sein Geschäft verrichten\""}, {"kategorie": "fig.", "text": "\"sein Soll erfüllen\""}, {"kategorie": "", "text": "\"sein Pflichtprogramm abspulen\""}, {"kategorie": "", "text": "\"seine Schuldigkeit tun\""}]'::jsonb, 'I hackl sicha nimma bis zum Umfoin - I leeg brav mei Krapfal oo, und damit hodsa si!'),
  ('i-hackl-sicha-nimma-bis-zum-umfoin-i-leeg-brav-mei-krapfal-oo-und-damit-hodsa-si', 'I hackl sicha nimma bis zum Umfoin - I leeg brav mei Krapfal oo, und damit hodsa si!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ich hackle sicher nimmer bis zum Umfallen - ich leg brav mein Krapferl ab, und damit hat sich''s!', '[{"kategorie": "wörtlich", "text": "\"Ich schufte bestimmt nicht mehr bis zum Umfallen – ich erledige meinen Teil und das war’s!\"  2. Ich arbeite nicht mehr bis zur völligen Erschöpfung – ich mache, was nötig ist, und dann ist Schluss!  3. Ich ackere nicht mehr, bis ich umfalle – ich erfülle mein Soll und gut ist''s!"}]'::jsonb, 'sei Krapfal ooleng'),
  ('do-schdeed-da-s-krapfal-ausse', 'Do schdeed da s''Krapfal ausse!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da steht dir das Krapferl raus!', '[{"kategorie": "wörtlich", "text": "\"Da kommt dir das Krapferl hoch!\"  2. (fig., scherzhaft für): Da geht einem der Hut hoch!  3. Da platzt einem der Kragen!  4. Da brennen einem die Sicherungen durch!"}]'::jsonb, ''),
  ('wem-an-fettn-kropfn-scheissn', 'wem an fettn Kropfn scheissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem einen fetten Krapfen scheißen', '[{"kategorie": "wörtlich", "text": "\"jemandem einen fetten Haufen vor die Tür setzen\""}, {"kategorie": "fig.", "text": "\"jemandem eine brüske Abfuhr erteilen\""}, {"kategorie": "", "text": "\"jemandem unmissverständlich zeigen, was man von ihm hält\""}, {"kategorie": "", "text": "\"jemanden eiskalt abservieren\""}]'::jsonb, 'Wiara mi schoo wiida um Gööd augschnoad hod, hob I eam an fettn Kropfn gschissn!'),
  ('wiara-mi-schoo-wiida-um-goeoed-augschnoad-hod-hob-i-eam-an-fettn-kropfn-gschissn', 'Wiara mi schoo wiida um Gööd augschnoad hod, hob I eam an fettn Kropfn gschissn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Als er mich schon wieder um Geld angeschnorrt hat, hab ich ihm einen fetten Krapfen geschissen!', '[{"kategorie": "wörtlich", "text": "\"Als er mich erneut um Geld angeschnorrt hat, hab ihn eiskalt abblitzen lassen!\"  2. Der wollte schon wieder Geld von mir – da hab ich ihm so einen Korb verpasst, dass er fast rückwärts rausgeflogen ist!  3. Als er wieder mit seiner Bettelei ankam und Geld von mir wollte, hab ich ihm eine beinharte Abfuhr erteilt!"}]'::jsonb, ''),
  ('auf-wos-an-fettn-kropfn-scheissn', 'auf wos an fettn Kropfn scheissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf etwas einen fetten Krapfen scheißen', '[{"kategorie": "wörtlich", "text": "\"keinen Deut auf etwas geben\""}, {"kategorie": "", "text": "\"auf etwas keinen feuchten Schas geben\""}, {"kategorie": "", "text": "\"auf etwas keinen Pfifferling geben\""}]'::jsonb, 'Ob de mi heiratn däd oda ned, auf des scheiss I an fettn Kropfn!'),
  ('ob-de-mi-heiratn-daed-oda-ned-auf-des-scheiss-i-an-fettn-kropfn', 'Ob de mi heiratn däd oda ned, auf des scheiss I an fettn Kropfn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ob die mich heiraten täte oder nicht, darauf scheiß ich einen fetten Krapfen!', '[{"kategorie": "wörtlich", "text": "\"Ob sie mich heiraten will oder nicht, ist mir scheißegal – ich pfeif drauf!\"  2. Ob die mich heiraten will oder nicht, kümmert mich nicht im Geringsten!\"  3. Ob sie Ja sagt oder nicht, das geht mir am Arsch vorbei!"}]'::jsonb, 'auf wos an fettn Kropfn scheissn'),
  ('i-scheiss-an-kropfn', 'I scheiss an Kropfn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich scheiße einen Krapfen!', '[{"kategorie": "wörtlich", "text": "\"Ich scheiße einen Haufen!\"  2. (fig., Ausruf der extremen Verwunderung): \"Das darf doch wohl nicht wahr sein!\"  3. \"Mich trifft der Schlag!\"  4. \"Ich glaub, ich spinne!\""}]'::jsonb, ''),
  ('do-scheiss-i-a-krapfal', 'Do scheiss I a Krapfal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da scheiß ich ein Krapferl!', '[{"kategorie": "wörtlich", "text": "\"Da scheiß ich ein Häufchen!\"  2. (fig., Ausruf der extremen Verwunderung): \"Das darf doch wohl nicht wahr sein!\"  3. \"Mich trifft der Schlag!\"  4. \"Ich glaub, ich spinne!\""}]'::jsonb, ''),
  ('i-scheiss-a-punschkrapfal', 'I scheiss a Punschkrapfal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich scheiße ein Punschkrapferl!', '[{"kategorie": "wörtlich", "text": "\"Ich scheiße einen Punschkrapfen!\"  2. (fig., Ausruf der extremen Verwunderung): \"Das darf doch wohl nicht wahr sein!\"  3. \"Mich trifft der Schlag!\"  4. \"Ich glaub, ich spinne!\""}]'::jsonb, ''),
  ('i-scheiss-mi-au', 'I scheiss mi au!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich scheiße mich an!', '[{"kategorie": "wörtlich", "text": "\"Ich scheiß mir in die Hose!\"  2. (fig., Ausruf der extremen Verwunderung): \"Das darf doch wohl nicht wahr sein!\"  3. \"Mich trifft der Schlag!\"  4. \"Ich glaub, ich spinne!\""}]'::jsonb, ''),
  ('ia-oida-is-a-echte-kraeaetzn', 'Ia Oida is a echte Kräätzn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ihr Alter ist eine echte Krätzen!', '[{"kategorie": "wörtlich", "text": "\"Ihr Alter ist ein echter Mistkerl!\"  2. Ihr Ehemann ist durch und durch ein mieser Kerl!"}, {"kategorie": "", "text": "Ihr Mann ist eine wahre Drecklaus!"}]'::jsonb, ''),
  ('i-winsch-dara-kraeaetzn-aum-oasch-und-z-kuaze-haend-zum-krotzn', 'I winsch dara Kräätzn aum Oasch und z''kuaze Händ zum Krotzn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich wünsche dir eine Krätze am Arsch und zu kurze Hände zum Kratzen!', '[{"kategorie": "wörtlich", "text": "\"Möge dein Arsch immer genau da jucken, wo deine Arme nicht hinkommen!\"  2. \"Ich wünsche dir ewigen Juckreiz, den du nicht wegkratzen kannst!\"  3. \"Ich wünsche dir ununterbrochenen Juckreiz, solange du lebst!“  4. “Möge dich das Leben mit ewigem Jucken strafen!\""}]'::jsonb, ''),
  ('si-woa-a-kraeaetzads-oeoelaend-mea-pustl-ois-mensch', 'Si woa a kräätzads Ööländ - mea Pustl ois Mensch!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Sie war ein krätzertes Elend – mehr Pustel als Mensch!', '[{"kategorie": "wörtlich", "text": "\"Sie war ein juckendes Wrack – Haut wie Hölle, gezeichnet von der Krätze!\"  2. Sie war ein wandelnder Juckreiz – rot, offen und krätzert bis zum Knochen!  3. Sie war so krätzegeplagt, sie hätte sich am liebsten mit einem Drahtbesen geduscht!"}]'::jsonb, ''),
  ('dea-typ-is-so-kraeaetzad-dass-soebst-de-flaeae-reissaus-neeman', 'Dea Typ is so kräätzad, dass söbst de Flää Reißaus neeman!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Typ ist so krätzert, dass selbst die Flöhe Reißaus nehmen!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist so eklig, dass selbst die Flöhe ihn meiden!\"  2. Der Kerl ist so widerwärtig, dass nicht mal die Würmer ihn anrühren!  3. Der Typ ist so ekelhaft, dass selbst Aasgeier einen Bogen um ihn machen!"}]'::jsonb, ''),
  ('wia-in-wean-kennan-nua-weisskraut-und-roodkraut-waunnsd-bei-uns-weisskoi-oda-roodkoi-beschdoeoest-waass-jeeda-glei-dassda-piefke-bist', 'Wia in Wean kennan nua ''Weisskraut'' und ''Roodkraut'' - waunnsd bei uns ''Weisskoi'' oda ''Roodkoi'' beschdööst, waass jeeda glei, dassda Piefke bist!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Wir in Wien kennen nur ''Weißkraut'' und ''Rotkraut'' - wenn du bei uns ''Weißkohl'' oder ''Rotkohl'' bestellst, weiß jeder gleich dass du ein Piefke bist!', '[{"kategorie": "wörtlich", "text": "\"Bei uns in Wien gibt’s nur ''Weißkraut'' und ''Rotkraut'' – wer bei uns ''Weißkohl'' oder ''Rotkohl'' bestellt,  outet sich als Nordlicht mit Sprachfehler!\"  2. Sagst du in Wien  statt ''Weißkraut'' und ''Rotkraut'' unglücklicherweise ''Weißkohl'' oder ''Rotkohl'', wissen die Leute sofort: Der kummt von über der Donau – und nicht vom richtigen Ufer!  3. Nur ein Piefke sogt ''Weißkohl'' oder ''Rotkohl'' – und der wird bei uns in Wien mit höflichem Schweigen ignoriert!"}]'::jsonb, ''),
  ('da-kraudara-vom-noschmoakd-hod-mea-gsaummaed-ois-vakaufd-owa-ea-woa-hoid-a-echts-wiina-original', 'Da Kraudara vom Noschmoakd hod mea gsaummäd ois vakaufd - owa ea woa hoid a echts Wiina Original!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Krauderer vom Naschmarkt hat mehr g’sammelt als verkauft – aber er war halt ein echtes Wiener Original!', '[{"kategorie": "wörtlich", "text": "\"Der Krauterer vom Naschmarkt war ein Standler mit Seele - mehr Sammler als Händler, aber ein echtes Wiener Original!\"  2. Was der Kleinhändler am Naschmarkt verkauft hat? Nix. Was er g’sammelt hat? Alles. Was er war? Eine echte Wiener Institution!  3. A Standl voll mit G’schichtln, a Kopf voll mit Schmäh – des war der Krauterer vom Naschmarkt!"}]'::jsonb, ''),
  ('bei-dem-kraudara-dauad-a-jeede-reparatua-drei-wochn-und-s-weakl-is-noochha-trotzdem-im-oasch', 'Bei dem Kraudara dauad a jeede Reparatua drei Wochn - und s''Weakl is noochha trotzdem im Oasch!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Bei dem Krauterer dauert jede Reparatur drei Wochen und das Werkl ist nachher trotzdem im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Bei diesem Dilettanten von Händler dauert jede Reparatur drei Wochen und das Gerät ist nachher trotzdem im Arsch!\"  2. Eine Reparatur bei diesem [[Weh]] von Händler dauert ewig - und nachher ist das Gerät kaputter als zuvor!  3. Der Pfuscher von Händler braucht drei Wochen für jede Reparatur – und hinterher ist das Teil trotzdem nur noch Schrott!"}]'::jsonb, ''),
  ('da-oide-kraudara-geed-nua-zum-wiatn-und-zum-greissla-ollas-aundare-is-eam-zu-modean', 'Da oide Kraudara geed nua zum Wiatn und zum Greissla - ollas aundare is eam zu modean!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der alte Krauderer geht nur zum Wirten und zum Greißler – alles andere is ihm zu modern!', '[{"kategorie": "wörtlich", "text": "\"Der alte Eigenbrötler geht nur zum Wirten und zum Greißler – alles andere is ihm zu modern!\"  2. Seine Welt hört beim Wirten und beim Greißler auf - alles andere ist dem alten Grantler zu modern!  3. Der alte Kauz lebt in einem Wien, das es nimmer gibt – nur beim Wirten und beim Greißler, wo die Zeit stehngeblieben ist, fühlt er sich noch daheim!"}]'::jsonb, ''),
  ('de-reebm-duat-hint-san-lauta-kraudara-wochsn-ned-troong-nix-und-saufn-nua-wossa', 'De Reebm duat hint san lauta Kraudara - wochsn ned, troong nix und saufn nua Wossa!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Reben dort hinten sind lauter Krauderer – wachsen nicht, tragen nichts und saufen nur Wasser!', '[{"kategorie": "wörtlich", "text": "\"Die Rebstöcke dort hinten sind nichts als dürres Gestrüpp - wachsen nicht, tragen nichts und saufen nur Wasser!\"  2. Diese verkümmerten Ranken taugen zu nichts – wuchern nicht, bringen keine Trauben und saugen Wasser auf wie ein Schwamm!  3. Mehr als vertrocknete Weinstöcke sind das nicht – faul, fruchtlos und versaufen unser ganzes Grundwasser!"}]'::jsonb, ''),
  ('oida-kraudara', 'Oida Kraudara!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Alter Krauterer!', '[{"kategorie": "wörtlich", "text": "\"Alter Knacker!\"  2. Du schepperter alter [[Zausel]]!  3. Du alter Eigenbrötler!  4. [[Du]] oida Tattara!"}]'::jsonb, ''),
  ('seit-drei-schdund-isa-draussd-beim-kraudan-i-glaub-dea-plant-a-ausgroowung', 'Seit drei Schdund isa draussd beim Kraudan - I glaub, dea plant a Ausgroowung!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Seit drei Stunden ist er draußen beim Krautern – ich glaube, der plant ''ne Ausgrabung!', '[{"kategorie": "wörtlich", "text": "\"Seit drei Stunden ist er draußen beim Unkrautjäten – ich glaube, der plant ''ne Ausgrabung!\"  2. Drei Stunden Unkraut zupfen? Ich glaub, der führt archäologische Grabungen durch!  3. Wenn der beim Unkrautzupfen noch ein paar Stunden so weitermacht, haben wir bald einen ''Canyon'' im Garten!"}]'::jsonb, ''),
  ('da-neiche-im-buero-tuad-in-gaunzn-toog-nua-umanaundkraudan-und-blaeaed-schaun', 'Da Neiche im Büro tuad in gaunzn Toog nua umanaundkraudan und blääd schaun!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Neue im Büro tut den ganzen Tag nur herumkraudern und blöd schauen!', '[{"kategorie": "wörtlich", "text": "\"Der Neue hängt den ganzen Tag nur planlos in der Gegend rum und schaut deppert!\"  2. Der Neue glotzt den ganzen Tag nur Löcher in die Luft und hängt blöd rum!  3. Anstatt zu arbeiten, dümpelt der Frischling nur träge vor sich hin und schaut dabei auch noch deppert!"}]'::jsonb, ''),
  ('dea-hoda-gschau-wiara-gatschbian-de-grod-wea-vom-regal-ghaut-hod', 'Dea hoda Gschau wiara Gatschbian, de grod wea vom Regal ghaut hod!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat ein G''schau wie eine Gatschbirne, die gerade wer vom Regal gehauen hat!', '[{"kategorie": "wörtlich", "text": "\"Der schaut drein wie ''ne Matschbirne, die grad jemand vom Regal gestoßen hat!\"  2. Der guckt wie ein plattgetretener Kaugummi mit Gesicht!  3. Der schaut aus wie ein zermatschter Kürbis nach Halloween!"}]'::jsonb, ''),
  ('i-hob-gestan-aum-moakd-a-muadstrumm-krauthappae-kaufd-des-reichd-fia-dreimoi-krautfleckaln', 'I hob gestan aum Moakd a muadstrumm Krauthappä kaufd - des reichd fia dreimoi Krautfleckaln!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich habe gestern am Markt ein mordstrumm Krauthappel gekauft – das reicht für dreimal Krautfleckerln!', '[{"kategorie": "wörtlich", "text": "\"Ich habe gestern am Markt ein riesiges Krauthäuptel gekauft – das reicht für dreimal Krautfleckerln!\"  2. Gestern hab ich am Markt ein Monster-Krauthappel ergattert – damit krieg ich ''ne halbe Kompanie satt!  3. Ich habe mir gestern am Markt einen riesengroßen Weißkohlkopf besorgt – der reicht für mehrere Portionen Krautfleckerl!"}]'::jsonb, ''),
  ('du-bist-villeichd-a-krauthappae-des-hob-i-da-do-schoo-gestan-eaklaead', 'Du bist villeichd a Krauthappä - des hob I da do schoo gestan eakläad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du bist vielleicht a Krauthappel – des hab ich dir doch gestern schon erklärt!', '[{"kategorie": "wörtlich", "text": "\"Mensch, du Hohlkopf – das hab ich dir doch schon gestern erklärt!\"  2. \"Du Dumpfbacke, hörst du eigentlich zu? Das hab ich dir doch schon gestern erklärt!\"  3. Du bist vielleicht eine Gatschbirne - wie oft soll ich’s dir noch vorkauen?"}]'::jsonb, ''),
  ('iwa-wean-glaenzd-a-goidanes-krauthappae-jo-so-haassd-bei-uns-de-wiina-secession-und-zwoa-weeng-iara-goidanan-kuppae', 'Iwa Wean glänzd a goidanes Krauthappä - jo, so haassd bei uns de Wiina Secession, und zwoa weeng iara goidanan Kuppä!', '', '', '', 'Wiener Architektur & Baukunst', 'Über Wien glänzt ein goldenes Krauthappel – ja, so heißt bei uns die Wiener Secession, und zwar wegen ihrer goldenen Kuppel!', '[{"kategorie": "wörtlich", "text": "\"Über Wien glänzt unser berühmtes ''Krauthappel'' – die Secession, unser goldener Kohlkopf!\"  2. Wir Wiener sagen Krauthappel – die Kunstfreunde nennen’s Secession!  3. Über Wien erhebt sich ein goldener Krautkopf – die Secession, Krone des Jugendstils!"}]'::jsonb, ''),
  ('a-krawattl-is-de-hundeleine-fias-buerovoik', 'A Krawattl is de Hundeleine fias Bürovoik!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Eine Krawatte ist die Hundeleine fürs Bürovolk!', '[{"kategorie": "wörtlich", "text": "\"Die Krawatte ist nichts anderes als die Würgeschlaufe für Bürohengste!\"  2. Die Krawatte ist der Kulturstrick für Schreibtischtäter!  3. Die Krawatte ist das goldene Halsband, das den Affen zum Manager macht!"}]'::jsonb, ''),
  ('wem-beim-krawattl-haum', 'wem beim Krawattl haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden beim Krawattl haben', '[{"kategorie": "wörtlich", "text": "\"jemanden bei der Krawatte haben\""}, {"kategorie": "", "text": "\"jemanden am Schlafittchen haben\""}, {"kategorie": "fig.", "text": "\"jemanden an der Kandare haben\""}, {"kategorie": "", "text": "\"jemanden am Wickel haben\""}]'::jsonb, 'Waunnsd mi no amoi so deppad auschausd, hob I di beim Krawattl!'),
  ('waunnsd-mi-no-amoi-so-deppad-auschausd-hob-i-di-beim-krawattl', 'Waunnsd mi no amoi so deppad auschausd, hob I di beim Krawattl!', '', '', '', 'Wiener Gaunersprache', 'Wenn du mich noch einmal so deppert anschaust, hab ich dich beim Krawattl!', '[{"kategorie": "wörtlich", "text": "\"Schau mich nicht so deppert an, sonst hab ich dich am Schlafittchen!\"  2. Glotz noch einmal so blöd, und ich hab dich am Kragen!  3. Noch so ein depperter Blick, und ich hab dich an der Kandare!"}]'::jsonb, 'wem beim Krawattl haum'),
  ('wem-beim-krawattl-pockn', 'wem beim Krawattl pockn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden beim Krawattl packen', '[{"kategorie": "wörtlich", "text": "\"jemanden bei der Krawatte packen\""}, {"kategorie": "", "text": "\"jemanden am Schlafittchen packen\""}, {"kategorie": "fig.", "text": "\"jemanden an die Kandare nehmen\""}, {"kategorie": "", "text": "\"jemanden am Wickel packen\""}]'::jsonb, 'Schau mi ned so deppad au, sunst pock I di beim Krawattl!'),
  ('schau-mi-ned-so-deppad-au-sunst-pock-i-di-beim-krawattl', 'Schau mi ned so deppad au, sunst pock I di beim Krawattl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schau mich nicht so deppert an, sonst pack ich dich beim Krawattl!', '[{"kategorie": "wörtlich", "text": "\"Schau mich nicht so saublöd an, sonst pack ich dich am Schlafittchen!\"  2. Glotz noch einmal so blöd, und ich pack dich am Kragen!  3. Noch so ein depperter Blick, und ich nehm dich an der Kandare!"}]'::jsonb, 'wem beim Krawattl pockn'),
  ('wem-beim-krawattl-neema', 'wem beim Krawattl neema', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden beim Krawattl nehmen', '[{"kategorie": "wörtlich", "text": "\"jemanden bei der Krawatte nehmen\""}, {"kategorie": "", "text": "\"jemanden am Schlafittchen packen\""}, {"kategorie": "fig.", "text": "\"jemanden an die Kandare nehmen\""}, {"kategorie": "", "text": "\"jemanden beim Wickel packen\""}]'::jsonb, 'De Schääfin nimmd an jeedn beim Krawattl, dea ned schbuad!'),
  ('de-schaeaefin-nimmd-an-jeedn-beim-krawattl-dea-ned-schbuad', 'De Schääfin nimmd an jeedn beim Krawattl, dea ned schbuad!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Chefin nimmt jeden beim Krawattl, der nicht spurt!', '[{"kategorie": "wörtlich", "text": "\"Die Chefin nimmt jeden an die Kandare, der nicht pariert!\"  2. Die Chefin greift sich jeden, der versucht, aus der Reihe zu tanzen!  3. Die Chefin hat jeden am Schlawittchen, der sich querlegt!"}]'::jsonb, 'wem beim Krawattl neema'),
  ('jetzd-hodan-beim-krawattl', 'Jetzd hodan beim Krawattl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Jetzt hat er ihn beim Krawattl!', '[{"kategorie": "wörtlich", "text": "Jetzt hat er ihn beim Schlawittchen!  2. Jetzt hat er ihn an der Kandare!  3. Jetzt hat er ihn am Wickel!  4. Jetzt hat er ihn in der [[Mangel]]!"}]'::jsonb, ''),
  ('ea-draad-eams-krawattl-auf-hoisweite-null', 'Ea draad eams Krawattl auf Hoisweite null!', '', '', '', 'Wiener Gaunersprache', 'Er dreht ihm die Krawatte auf Halsweite null', '[{"kategorie": "wörtlich", "text": "\"Er dreht ihm den Hals um!\"  2. \"Er zieht ihm den Strick enger, bis nix mehr geht!\"  3. [[Ea]] draad eam de Gaas oo!  4. Er zieht die Daumenschrauben auf Anschlag!  5.  Er dreht ihm die Luft ab!"}]'::jsonb, ''),
  ('waunn-da-schiri-den-oeoefa-gibd-kragl-i-eam-heechstpeaseenlich-oo', 'Waunn da Schiri den Ööfa gibd, kragl I eam heechstpeaseenlich oo!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wenn der Schiri den Elfer gibt, kragl'' ich ihn höchstpersönlich ab!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Schiedsrichter den Elfer gibt, dreh ich ihm eigenhändig den Hals um!\"  2. Wenn der Schiedsrichter den Strafstoß gibt, dreh ich ihm den Kragen um - und zwar eigenhändig!  3. Wenn der Schiri auf Elfmeter entscheidet, drehe ich ihm eigenhändig die Halsweite auf Null!"}]'::jsonb, ''),
  ('wems-krawattl-auf-hoisweite-nui-draan', 'wems Krawattl auf Hoisweite Nui draan', '', '', '', 'Wiener Gaunersprache', 'jemandem die Krawatte auf Halsweite Null drehen', '[{"kategorie": "scherzhaft für", "text": "\"jemandem den Hals umdrehen\""}, {"kategorie": "allg.", "text": "\"jemandem die Luft abdrehen, bis er verreckt\""}, {"kategorie": "", "text": "\"jemandem die Gas abdrehen\" (=jemanden  umbringen, erwürgen, [[abkrageln]])"}]'::jsonb, 'Waunna de Marii bis muang in da Frua ned ausseruckd, draar I eam s''Krawattl auf Hoisweite Nui!'),
  ('waunna-de-marii-bis-muang-in-da-frua-ned-ausseruckd-draar-i-eam-s-krawattl-auf-hoisweite-nui', 'Waunna de Marii bis muang in da Frua ned ausseruckd, draar I eam s''Krawattl auf Hoisweite Nui!', '', '', '', 'Wiener Gaunersprache', 'Wenn er die Marie bis morgen in der Früh nicht rausrückt, dreh ich ihm das Krawattl auf Halsweite Null!', '[{"kategorie": "wörtlich", "text": "\"Wenn er die Kohle bis morgen in der Früh nicht rausrückt, dreh ich ihm eigenhändig den Hals um!\"  2. Wenn er das Geld bis morgen früh nicht auf den Tisch legt, schnür ich ihm eigenhändig die Luft ab, bis er verreckt!  3. Wenn er das Geld nicht bis Sonnenaufgang zahlt, brech ich ihm den Kragen!"}]'::jsonb, 'wems Krawattl auf Hoisweite Nui draan'),
  ('wia-brauchn-an-belkanto-ned-an-krawattltenoa', 'Wia brauchn an Belkanto - ned an Krawattltenoa!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wir brauchen einen Belcanto - nicht einen Krawattltenor!', '[{"kategorie": "wörtlich", "text": "\"Wir brauchen einen Belcanto-Tenor - nicht einen Kopfstimmenkrächzer!\"  2. Wir brauchen einen Heldentenor und keinen Falsettierer!  3. Wir brauchen einen Belcanto-Tenor – keinen Möchtegern-Papageno im Stimmbruch!"}]'::jsonb, ''),
  ('waunn-de-oide-kraxn-lochd-friada-s-bia-in-da-haund-ei', 'Waunn de oide Kraxn lochd, friada s''Bia in da Haund ei!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn die alte Kraxen lacht, friert dir das Bier in der Hand ein!', '[{"kategorie": "wörtlich", "text": "\"Wenn die alte Schabracke lacht, friert dir das Bier in der Hand ein!\"  2. Ein einziges Kichern von dieser alten Kellerhexe, und das Bier bleibt dir in der Kehle stecken!  3. Wenn diese alte [[Grammel]] lacht, friert dir die Seele ein!"}]'::jsonb, ''),
  ('de-klimaaunloog-in-dera-kraxn-is-des-loch-im-boodnblech', 'De Klimaaunloog in dera Kraxn is des Loch im Boodnblech!', '', '', '', 'Wiener Mechaniker-Slang', 'Die Klimaanlage in dieser Kraxen ist das Loch im Bodenblech!', '[{"kategorie": "wörtlich", "text": "\"Die Klimaanlage in dieser Schrottkiste ist das Loch im Bodenblech!\"  2. Als Klimaanlage fungiert bei dieser Rostlaube das Loch im Fußraum!  3. Statt Klimaanlage verfügt dieses Schrottmobil über eine natürliche Belüftung – die Luft pfeift durch das Loch im Bodenblech!"}]'::jsonb, ''),
  ('a-kraxn-is-a-troogegschdoeoe-fian-buugl-mit-dem-d-leid-friara-hoiz-hei-und-leebmsmittl-mueuesaum-in-beag-auffe-und-owe-gschleppd-haum', 'A Kraxn is a Troogegschdöö fian Buugl, mit dem d''Leid friara Hoiz, Hei und Leebmsmittl müüsaum in Beag auffe und owe gschleppd haum!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Kraxen ist ein Tragegestell für den Buckel, mit dem die Leute früher Holz, Heu und Lebensmittel mühsam den Berg hinauf und hinunter geschleppt haben!', '[{"kategorie": "wörtlich", "text": "\"Die Kraxen ist ein auf dem Rücken zu tragendes Gestell, mit dem Menschen über Jahrhunderte Holz, Heu, Lebensmittel oder Waren mühsam bergauf und bergab transportiert haben!\"  2. Die Kraxen war jahrhundertelang das wichtigste Hilfsmittel, um schwere Lasten auf dem Rücken über Berge und Täler zu tragen!  3. Mit der Kraxen auf dem Rücken schleppten Generationen von Bauern, Knechten und Händlern Holz, Heu und Lebensmittel durch steiles Gelände!"}]'::jsonb, ''),
  ('de-kopfkraxn-woa-greessa-ois-ea-soeoewae-von-hintn-host-nua-no-seine-fiass-gseeng', 'De Kopfkraxn woa greessa ois ea sööwä - von hintn host nua no seine Fiass gseeng!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Kopfkraxen war größer als er selber – von hinten hast du nur noch seine Füße gesehen!', '[{"kategorie": "wörtlich", "text": "\"Der Rückentragekorb mit Überbau  war höher als er selbst – übrig blieben nur zwei Füße, die unten rausgestakst sind!\"  2. Der Rückentragekorb war größer als er selbst – von hinten war nur noch ein laufender Heuhaufen mit zwei Füßen zu erkennen!  3. Er war so beladen, dass er unter der Kopfkraxen fast verschwand – sichtbar blieben nur noch seine Schritte!"}]'::jsonb, ''),
  ('mit-da-oimkraxn-haum-de-beagbauan-friara-de-mueuech-und-in-kaas-von-da-oim-owe-ins-toi-troong', 'Mit da Oimkraxn haum de Beagbauan friara de Müüch und in Kaas von da Oim owe ins Toi troong!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Mit der Almkraxen haben die Bergbauern früher die Milch und den Käse von der Alm runter ins Tal getragen!', '[{"kategorie": "wörtlich", "text": "\"Früher schleppten die Bergbauern Milch und Käse mit dem Almtragekorb hinunter ins Tal!\"  2. Die Bergbauern nutzten früher die Almkraxen, um Milch und Käse ins Tal zu bringen!  3. Milch und Käse wurden einst mit Hilfe eines Rückentragekorbs von der Alm ins Tal befördert!"}]'::jsonb, ''),
  ('in-da-buuglkraxn-haum-de-waundahaendla-friara-eanare-woan-transpoatiad', 'In da Buuglkraxn haum de Waundahändla friara eanare Woan transpoatiad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'In der Buckelkraxen haben die Wanderhändler früher ihre Waren transportiert!', '[{"kategorie": "wörtlich", "text": "\"Früher transportierten die Wanderhändler ihre Waren in einem Rückentragekorb von Ort zu Ort!\"  2. Mit der Buckelkraxen auf dem Rücken zogen einst die Händler durch die Lande, beladen mit allerlei Waren!  3. Die Buckelkraxen war das Rückgrat des Wanderhandels – prall gefüllt mit Stoffen, Werkzeugen und Waren aller Art!"}]'::jsonb, ''),
  ('wem-buuglkraxn-trogn', 'wem Buuglkraxn trogn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden Buckelkraxen tragen', '[{"kategorie": "wörtlich", "text": "\"jemanden wie eine Buckelkrächse tragen\" [\"Buckelkrächse\" = (hist.) \"Rückentragekorb\" (stabiles Rückengestell zum Lastentragen, wie es wandernde Händler, Bauersknechte oder Holzknechte nutzten)"}, {"kategorie": "allg.", "text": "\"jemanden huckepack tragen\""}, {"kategorie": "", "text": "\"jemanden auf dem Rücken tragen\""}]'::jsonb, ''),
  ('ea-woa-deamaassn-im-oeoe-dass-eam-sei-haawara-buuglkraxn-zua-u-baun-troong-hod-miassn', 'Ea woa deamaassn im Öö, dass eam sei Haawara Buuglkraxn zua U-Baun troong hod miassn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er war dermaßen im Öl, dass ihn sein Haberer Buckelkraxen zur U-Bahn tragen hat müssen!', '[{"kategorie": "wörtlich", "text": "\"Er war so sturzbetrunken, dass ihn sein Kumpel huckepack zur U-Bahn tragen musste!\"  2. Der war so voll wie ein Fass, sein Kumpel musste ihn huckepack bis zur U-Bahn schleppen!  3. Volltrunken hing er auf dem Rücken seines Freundes, der ihn huckepack zur U-Bahn tragen musste!"}]'::jsonb, 'wem Buuglkraxn trogn'),
  ('wem-buuglkraxn-neema', 'wem Buuglkraxn neema', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden Buckelkraxen nehmen', '[{"kategorie": "wörtlich", "text": "\"jemanden wie eine Buckelkrächse nehmen\" [\"Buckelkrächse\" = (hist.) \"Rückentragekorb\" (stabiles Rückengestell zum Lastentragen, wie es wandernde Händler, Bauersknechte oder Holzknechte nutzten)"}, {"kategorie": "allg.", "text": "\"jemanden huckepack nehmen\""}, {"kategorie": "", "text": "\"jemanden auf den Rücken nehmen\""}]'::jsonb, ''),
  ('de-klaane-hod-ian-bruadan-buuglkraxn-gnumma-und-is-mid-eam-duachs-gaunze-haus-galoppiad', 'De Klaane hod ian Bruadan Buuglkraxn gnumma und is mid eam duachs gaunze Haus galoppiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Kleine hat ihren Bruder Buckelkraxen genommen und ist mit ihm durchs ganze Haus galoppiert!', '[{"kategorie": "wörtlich", "text": "\"Die Kleine hat ihren Bruder huckepack genommen und ist mit ihm durchs ganze Haus galoppiert!\"  2. Die Kleine schnappte sich ihren Bruder auf den Rücken und galoppierte mit ihm wie ein Pferd durchs ganze Haus!  3. Mit ihrem Bruder huckepack sauste sie wie der Blitz durchs ganze Haus!"}]'::jsonb, 'wem Buuglkraxn neema'),
  ('de-zniachte-kraxn-schdeed-scho-seit-zwanzg-joa-laeaea-kaa-wunda-dass-es-dachl-laungsaum-eibrichd', 'De zniachte Kraxn schdeed scho seit zwanzg Joa lääa - kaa Wunda, dass es Dachl laungsaum eibrichd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die zunichte Kraxen steht schon seit zwanzig Jahren leer – kein Wunder, dass das Dach langsam einbricht!', '[{"kategorie": "wörtlich", "text": "\"Das baufällige Althaus steht schon seit zwanzig Jahren leer – kein Wunder, dass das Dach langsam einbricht!\"  2. Zwanzig Jahre hat die alte Hütte keinen Menschen mehr gesehen – jetzt senkt sich das Dach wie ein müder Rücken!  3. Das verwahrloste Haus vegetiert seit zwanzig Jahren dahin, und nun beugt sich sogar das Dach dem Zahn der Zeit!"}]'::jsonb, ''),
  ('kraxntrooga-woa-ka-leichte-hockn-oft-host-mea-ois-dei-eigans-gwichd-aum-buugl-troong-miassn', 'Kraxntrooga woa ka leichte Hockn - oft host mea ois dei eigans Gwichd aum Buugl troong miassn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Kraxenträger war keine leichte Hacken - oft hast du mehr als dein eigenes Gewicht am Buckel tragen müssen!', '[{"kategorie": "wörtlich", "text": "\"Krächsenträger war kein leichter Job - oft musste man mehr als sein eigenes Gewicht am Rücken tragen!\"  2. Kraxenträger sein war kein Zuckerschlecken – oft schleppte man mehr als das eigene Körpergewicht auf dem Buckel!  3. Die Träger der riesigen Rückenkörbe waren nicht zu beneiden - oft trugen sie die doppelte Last ihres Gewichts durchs Gebirge!"}]'::jsonb, ''),
  ('moch-endlich-dei-kraxn-untan-vatroog', 'Moch endlich dei Kraxn untan Vatroog!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Mach endlich deine Kraxen unter den Vertrag!', '[{"kategorie": "wörtlich", "text": "\"Mach endlich deine Paraphe unter den Vertragstext!\"  2. Kritzel endlich deinen Namenszug unter den Vertragstext!  3. Setz endlich deine Initialien unter den Vertrag!"}]'::jsonb, ''),
  ('mit-dera-kraxn-kummst-ned-weit', 'Mit dera Kraxn kummst ned weit!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit dieser Kraxen kommst du nicht weit!', '[{"kategorie": "wörtlich", "text": "\"Mit dieser Klapperkiste kommst du nicht weit!\"  2. Mit dieser Rostlaube kommst du nicht einmal mehr bis zur nächsten Tankstelle!  3. Mit der Karre kommst du höchstens bis zur nächsten Werkstatt – wenn du Glück hast!"}]'::jsonb, ''),
  ('den-sei-gree-wiad-boid-vagee', 'Den sei Gree wiad boid vagee!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der Kren von ihm wird bald vergehen!', '[{"kategorie": "wörtlich", "text": "\"Sein Hochmut wird ihm bald vergehen!\"  2. Sein Stolz wird nicht von Dauer sein!  3. Seine Überheblichkeit wird bald verfliegen!"}]'::jsonb, ''),
  ('waunnsd-de-weissn-blia-vom-gree-siichsd-daedast-ni-glaum-wos-fiara-feia-in-seina-wuazl-schlummad', 'Waunnsd de weissn Blia vom Gree siichsd, dädast ni glaum, wos fiara Feia in seina Wuazl schlummad!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Wenn du die weißen Blüten vom Kren siehst, tätest du nie glauben, welches Feuer in seiner Wurzel schlummert!', '[{"kategorie": "wörtlich", "text": "\"Zwischen den weißen Blüten des Krens ahnt man nicht die feurige Kraft, die in seiner Wurzel schlummert!\"  2. Die weiße Blütenpracht des Krens lässt kaum erahnen, welch brennende Schärfe in seiner Wurzel tief in der Erde schlummert!  3. Unter dem blütenweißen Kleid des Krens verbirgt sich ein Wurzelherz, das erst in der Küche so richtig zu lodern beginnt!"}]'::jsonb, ''),
  ('oida-reib-ume-a-haasse-mid-an-sauschoafn-gree-auf-dass-ma-s-hian-aussefoeoend', 'Oida, reib ume a Haasse mid an sauschoafn Gree, auf dass ma s''Hian ausseföönd!', '', '', '', 'Wiener Würstelstandjargon', 'Alter, reib rüber ''ne Heiße Wurst mit einem sauscharfen Kren, auf dass es mir das Hirn rausföhnt!', '[{"kategorie": "wörtlich", "text": "\"Alter, ich hätte gerne eine heiße Wurst mit richtig scharfem Meerrettich – so scharf, dass mir die Nebenhöhlen durchgepustet werden!\"  2. Mann, gib mir ''ne Burenwurst mit sauscharfem Kren, der bis in die Stirnhöhlen pfeift!  3. Kumpel, schmeiß rüber ''ne Wurst mit so viel Kren, dass das Hirn auf Durchzug geht!"}]'::jsonb, ''),
  ('auf-wos-a-gree-sei', 'auf wos a Gree sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf etwas ein Kren sein', '[{"kategorie": "wörtlich", "text": "\"auf etwas scharf sein\""}, {"kategorie": "", "text": "\"darauf brennen, etwas zu haben\""}, {"kategorie": "", "text": "\"ein Fan von etwas sein\""}, {"kategorie": "", "text": "[[sich]] um etwas reißen"}]'::jsonb, 'De Buama san auf de neichn Packln a Gree - de schboan scho seit an Joa drauf!'),
  ('de-buama-san-auf-de-neichn-packln-a-gree-de-schboan-scho-seit-an-joa-drauf', 'De Buama san auf de neichn Packln a Gree - de schboan scho seit an Joa drauf!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Buben sind auf die neuen Packeln ein Kren – die sparen schon seit einem Jahr drauf!', '[{"kategorie": "wörtlich", "text": "\"Die Buben brennen wie wild auf die neuen Fußballschuhe – sie sparen schon seit einem Jahr darauf!\"  2. Die Buben sind scharf auf die neuen Fußballschuhe – das Sparschwein wird seit einem Jahr dafür gefüttert!  3. Die Jungs fiebern den neuen Fußballschuhen entgegen und sparen seit einem Jahr dafür!"}]'::jsonb, 'auf wos a Gree sei'),
  ('i-bin-da-gree-von-eam', 'I bin da Gree von eam!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Ich bin der Kren von ihm!', '[{"kategorie": "wörtlich", "text": "\"Ich bin sein Mäzen und Förderer!\"  2. \"Ich bin sein wohlwollender Mentor!\"  3. Ich stehe ihm als Gönner zur Seite!"}]'::jsonb, ''),
  ('sein-gree-dazuageem', 'sein Gree dazuageem', '', '', '', 'Wiener Sprüche, die sitzen!', 'seinen Kren dazugeben', '[{"kategorie": "wörtlich", "text": "\"ungefragt seine Meinung äußern\""}, {"kategorie": "", "text": "\"seinen [[Senf]] dazugeben\""}, {"kategorie": "", "text": "\"ungefragt einen mehr oder weniger entbehrlichen Kommentar abgeben\""}, {"kategorie": "", "text": "\"ungefragt überall mitreden\""}]'::jsonb, 'Ea hod von nix a Aunung, gibd beim Dischkutian owa imma sein Gree dazua!'),
  ('ea-hod-von-nix-a-aunung-gibd-beim-dischkutian-owa-imma-sein-gree-dazua', 'Ea hod von nix a Aunung, gibd beim Dischkutian owa imma sein Gree dazua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat von nichts eine Ahnung, gibt beim Dischkutieren aber immer seinen kren dazu!', '[{"kategorie": "wörtlich", "text": "\"Er versteht überhaupt nichts, muss aber in jeder Diskussion seinen Senf dazugeben!\"  2. Er hat null Ahnung, meldet sich aber ständig zu Wort!  3. Er hat von Tuten und Blasen keine Ahnung, redet aber trotzdem überall mit!"}]'::jsonb, 'sein Gree dazuageem'),
  ('sein-senf-dazuageem', 'sein Senf dazuageem', '', '', '', 'Wiener Sprüche, die sitzen!', 'seinen Senf dazugeben', '[{"kategorie": "wörtlich", "text": "\"ungefragt seine Meinung äußern\""}, {"kategorie": "", "text": "\"seinen [[Kren]] dazugeben\""}, {"kategorie": "", "text": "\"ungefragt einen mehr oder weniger entbehrlichen Kommentar abgeben\""}, {"kategorie": "", "text": "\"ungefragt überall mitreden\""}]'::jsonb, 'De Oide is blääd wiara Binkl Fetzn, muass owa iwaroi ian Senf dazuageem!'),
  ('an-gree-brauchad-ma', 'An Gree brauchad ma!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Einen Kren bräuchten wir!', '[{"kategorie": "wörtlich", "text": "\"Wir bräuchten einen edlen Spender!\"  2. \"Wir bräuchten einen reichen Mäzen!\"  3. \"Was wir bräuchten, ist ein edler Geldgeber!\""}]'::jsonb, ''),
  ('si-an-gree-geem', 'si an Gree geem', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen Kren geben', '[{"kategorie": "wörtlich", "text": "\"sich einen vornehmen Touch geben\""}, {"kategorie": "", "text": "\"sich vornehm gebärden\""}, {"kategorie": "", "text": "\"den feinen Herren spielen\""}]'::jsonb, 'Ea gibd si an Gree, dabei isa ned vüü mea ois a Nuudlaug im Aunzug!'),
  ('ea-gibd-si-an-gree-dabei-isa-ned-vueue-mea-ois-a-nuudlaug-im-aunzug', 'Ea gibd si an Gree, dabei isa ned vüü mea ois a Nuudlaug im Aunzug!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Er gibt sich einen Kren, dabei ist er nicht viel mehr als ein Nudelaug'' im Anzug!', '[{"kategorie": "wörtlich", "text": "\"Er spielt den feinen Herrn, dabei ist er nicht viel mehr als ein Trottel im Zweiteiler!\"  2. Er spielt den Aristokraten, ist aber nicht mehr als ein Hosenscheißer im Zwirn!  3. Er versucht den Dandy, sieht aber eher aus wie ein Depp im Maßanzug!"}]'::jsonb, 'si an Gree geem'),
  ('an-gree-mochn', 'an Gree mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Kren machen', '[{"kategorie": "wörtlich", "text": "\"auf vornehm machen\""}, {"kategorie": "", "text": "\"sich vornehm gebärden\""}, {"kategorie": "", "text": "\"den feinen Herren spielen\""}]'::jsonb, 'An Gree mochn is leichda ois a Gree sei!'),
  ('an-gree-mochn-is-leichda-ois-a-gree-sei', 'An Gree mochn is leichda ois a Gree sei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Einen Kren zu machen ist leichter, als ein Kren zu sein!', '[{"kategorie": "wörtlich", "text": "\"Den feinen Herrn zu spielen ist leichter, als ein feiner Herr zu sein!\"  2. Sich als feiner Herr zu geben, ist einfacher, als wirklich einer zu sein!  3. Den feinen Pinkel markieren kann jeder – aber wirklich einer sein, das ist die Kunst!"}]'::jsonb, 'an Gree mochn'),
  ('fia-sowos-do-bin-i-a-gree', 'Fia sowos do bin I a Gree!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Für so etwas, da bin ich ein Kren!', '[{"kategorie": "wörtlich", "text": "\"Für so etwas bin ich in der Sekunde zu haben!\"  2. Darauf bin ich seit jeher scharf!  3. Darauf brenne ich wie wild!"}]'::jsonb, ''),
  ('da-gree-sei', 'da Gree sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'der Kren sein', '[{"kategorie": "wörtlich", "text": "\"der wohlhabende Gönner sein\""}, {"kategorie": "", "text": "\"der reiche Mäzen sein\""}, {"kategorie": "", "text": "\"der Geldgeber sein\""}, {"kategorie": "Gaunersprache", "text": "\"der \"Spendierer\" sein\""}, {"kategorie": "", "text": "\"der Geneppte sein\""}]'::jsonb, 'I bin da Gree von eam!'),
  ('a-mandl-mit-gree', 'a Mandl mit Gree', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein Mannsbild mit Kren', '[{"kategorie": "wörtlich", "text": "\"ein Mann mit viel Geld\""}, {"kategorie": "", "text": "\"ein wohlhabender Mann\""}, {"kategorie": "", "text": "\"ein Mann mit dem nötigen Kleingeld\""}, {"kategorie": "", "text": "\"ein gutsituierter Mann\""}]'::jsonb, 'De heirad easchd, waunn sa si a Mandl mit Gree gaungld hod!'),
  ('de-heirad-easchd-waunn-sa-si-a-mandl-mit-gree-gaungld-hod', 'De heirad easchd, waunn sa si a Mandl mit Gree gaungld hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die heiratet erst, wenn sie sich ein Mandl mit Kren geangelt hat!', '[{"kategorie": "wörtlich", "text": "\"Die heiratet erst, wenn sie sich ein Mannsbild mit dem nötigen Kleingeld geangelt hat!\"  2. Die tritt erst vor den Altar, wenn ihr ein reicher Geldsack über den Weg läuft!  3. Die kriegt nur dann Ja-Sager-Laune, wenn ein Goldesel daherkommt!"}]'::jsonb, 'a Mandl mit Gree'),
  ('da-gree-dea-bin-imma-i', 'Da Gree, dea bin imma I!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Kren, der bin immer ich!', '[{"kategorie": "wörtlich", "text": "\"Der, der zahlt, das bin immer ich!\"  2. \"Derjenige mit den Spendierhosen, das bin immer ich!\"  3. Wenn’s ans Zahlen geht, bin immer ich dran!"}]'::jsonb, 'da Gree sei'),
  ('zum-greereim-sei', 'zum Greereim sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'zum Krenreiben sein', '[{"kategorie": "wörtlich", "text": "\"zu nichts zu gebrauchen sein\""}, {"kategorie": "", "text": "\"zu nichts taugen\""}, {"kategorie": "", "text": "\"zum Vergessen sein\""}]'::jsonb, 'De Oide is zum Greereim - schiach, fäu und oomdrei aa noo laut!'),
  ('de-oide-is-zum-greereim-schiach-faeu-und-oomdrei-aa-noo-laut', 'De Oide is zum Greereim - schiach, fäu und oomdrei aa noo laut!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Alte ist zum Krenreiben - schirch, faul und obendrein auch noch laut!', '[{"kategorie": "wörtlich", "text": "\"Die Alte ist zu nichts zu gebrauchen - unattraktiv, faul und obendrein auch noch laut!\"  2. Die Frau taugt zu nichts außer zum Krenreiben - nicht zum Anschauen, nicht zum Arbeiten, aber immer laut!  3. Mit diesem Weib ist nichts anzufangen – weder schön noch tüchtig, dafür aber immer laut!"}]'::jsonb, 'zum Greereim sei'),
  ('da-heechsde-gree', 'da heechsde Gree', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der höchste Kren', '[{"kategorie": "", "text": "\"der Gipfel der Lächerlichkeit\""}, {"kategorie": "", "text": "\"die Krönung des Irrsinns\""}, {"kategorie": "", "text": "\"der Höhepunkt des Skurrilen\""}]'::jsonb, 'Da heechsde Gree woa sei Auftritt im goidanan Treeningsaunzug!'),
  ('da-heechsde-gree-woa-sei-auftritt-im-goidanan-treeningsaunzug', 'Da heechsde Gree woa sei Auftritt im goidanan Treeningsaunzug!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der höchste Kren war sein Auftritt im goldenen Trainingsanzug!', '[{"kategorie": "wörtlich", "text": "\"Der Gipfel der Lächerlichkeit war sein Auftritt im goldenen Trainingsanzug!\"  2. Die Krönung des Irrsinns war sein Auftritt im goldenen Trainingsanzug!  3. Der Höhepunkt des Skurrilen war sein Auftritt im goldenen Trainingsanzug!"}]'::jsonb, ''),
  ('an-gree-reissn', 'an Gree reissn', '', '', '', 'Wiener Küche & Gaumenfreuden', 'einen Kren reißen', '[{"kategorie": "wörtlich", "text": "\"einen Kren reißen\""}, {"kategorie": "Küchenjargon", "text": "\"Kren reiben\" (auf einem Gemüsehobel \"zerreißen\" [=schaben])"}, {"kategorie": "fig.", "text": "sich wichtigmachen, angeben, großtun, den feinen Herren spielen"}]'::jsonb, 'An Gree reissn is leichda ois a Gree sei!'),
  ('an-gree-reissn-is-leichda-ois-a-gree-sei', 'An Gree reissn is leichda ois a Gree sei!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einen Kren zu reißen ist leichter, als ein Kren zu sein!', '[{"kategorie": "wörtlich", "text": "\"Den feinen Herrn zu spielen ist leichter, als ein feiner Herr zu sein!\"  2. Sich als feiner Herr zu geben, ist einfacher, als wirklich einer zu sein!  3. Den feinen Pinkel markieren kann jeder – aber wirklich einer sein, das ist die Kunst!"}]'::jsonb, 'an Gree reissn'),
  ('so-wia-du-in-gree-reissd-samma-bis-oostan-ned-featich', 'So wia du in Gree reissd, samma bis Oostan ned featich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'So wie du den Kren reißt, sind wir bis Ostern nicht fertig!', '[{"kategorie": "wörtlich", "text": "\"So wie du den Kren reibst, sind wir bis Ostern nicht fertig!\"  2. Bei der Geschwindigkeit kannst den Kren gleich mit’m Löffel streicheln statt ihn zu reißen!  3. Wenn du den Kren in diesem Tempo weiterreibst, sind wir nächstes Jahr noch nicht fertig!"}]'::jsonb, ''),
  ('wem-zum-greereissn-brauchn', 'wem zum Greereissn brauchn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden zum Krenreißen brauchen', '[{"kategorie": "wörtlich", "text": "\"jemanden nur zum Krenreiben gebrauchen können\""}, {"kategorie": "", "text": "\"jemanden nur für einfachste Handlangerdienste einsetzen können\""}, {"kategorie": "", "text": "\"jemanden höchstens zum Türaufhalten gebrauchen können\""}]'::jsonb, 'Waunn I den zu wos brauch, daunn heechstns zum Greereissn!'),
  ('waunn-i-den-zu-wos-brauch-daunn-heechstns-zum-greereissn', 'Waunn I den zu wos brauch, daunn heechstns zum Greereissn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich den zu etwas brauche, dann höchstens zum Krenreißen!', '[{"kategorie": "wörtlich", "text": "\"Der ist so nutzlos, den kannst höchstens zum Krenreiben brauchen!\"  2. Der ist so nutzlos wie ein Kropf!  3. Der ist so nutzlos, den kannst höchstens als Briefbeschwerer brauchen!"}]'::jsonb, 'wem zum Greereissn brauchn'),
  ('des-kreweechal-schaut-aus-ois-haed-eam-da-teifae-beim-aussiam-iwaseeng', 'Des Kreweechal schaut aus, ois häd eam da Teifä beim Aussiam iwaseeng!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieses Krewecherl schaut aus, als hätte ihn der Teufel beim Aussieben übersehen!', '[{"kategorie": "wörtlich", "text": "\"Dieser Jammerlappen sieht aus, als hätte ihn der Teufel beim Aussieben übersehen!\"  2. Der Typ sieht so ausgehungert und mickrig aus, als hätte ihn der Teufel beim Aussieben übriggelassen!  3. An diesem Hungerhaken ist so wenig dran, den hat der Teufel beim Aussieben wohl vergessen!"}]'::jsonb, ''),
  ('des-krischpindl-muassd-aum-zaun-aubindn-sunst-fliagda-da-davoo', 'Des Krischpindl muassd aum Zaun aubindn, sunst fliagda da davoo!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieses Krischpindl musst du am Zaun anbinden, sonst fliegt er dir davon!', '[{"kategorie": "wörtlich", "text": "\"Diesen Hungerhaken musst du am Zaun anbinden, sonst fliegt er dir davon!\"  2. So dünn wie der ist, brauchst du Gewichte an den Füßen, sonst hebt er ab!  3. Den musst du festhalten, wenn’s zieht – sonst macht der den Abflug!"}]'::jsonb, ''),
  ('des-raunkal-muassd-aum-zaun-aubindn-sunst-fliagda-da-davoo', 'Des Raunkal muassd aum Zaun aubindn, sunst fliagda da davoo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieses Rankerl musst du am Zaun anbinden, sonst fliegt er dir davon!', '[{"kategorie": "wörtlich", "text": "\"Diesen Hungerhaken musst du am Zaun anbinden, sonst fliegt er dir davon!\"  2. So dünn wie der ist, brauchst du Gewichte an den Füßen, sonst hebt er ab!  3. Den musst du festhalten, wenn’s zieht – sonst macht der den Abflug!"}]'::jsonb, ''),
  ('des-zaunraunkal-muassd-aum-gitta-aubindn-sunst-fliagda-da-davoo', 'Des Zaunraunkal muassd aum Gitta aubindn, sunst fliagda da davoo!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieses Zaunrankerl musst du am Gitter anbinden, sonst fliegt er dir davon!', '[{"kategorie": "wörtlich", "text": "\"Diesen Hungerhaken musst du am Zaun anbinden, sonst fliegt er dir davon!\"  2. So dünn wie der ist, brauchst du Gewichte an den Füßen, sonst hebt er ab!  3. Den musst du festhalten, wenn’s zieht – sonst macht der den Abflug!"}]'::jsonb, ''),
  ('jetza-is-ma-scho-wiida-so-a-krischpl-unta-de-zaehnd-kumma', 'Jetza is ma scho wiida so a Krischpl unta de Zähnd kumma!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Jetzt ist mir schon wieder so ein Krischpel unter die Zähne gekommen!', '[{"kategorie": "wörtlich", "text": "\"Jetzt ist mir schon wieder so ein Fleischknorpelstück unter die Zähne gerutscht!\"  2. Jetzt habe ich schon wieder auf so ein zähes Knorpelstück gebissen!  3. Schon wieder ein Knorpel – das verdirbt einem echt jeden Bissen!"}]'::jsonb, ''),
  ('des-krischpl-muassd-aum-zaun-aubindn-sunst-fliagda-da-davoo', 'Des Krischpl muassd aum Zaun aubindn, sunst fliagda da davoo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dieses Krischpl musst du am Zaun anbinden, sonst fliegt er dir davon!', '[{"kategorie": "wörtlich", "text": "\"Diesen Hungerhaken musst du am Zaun anbinden, sonst fliegt er dir davon!\"  2. So dünn wie der ist, brauchst du Gewichte an den Füßen, sonst hebt er ab!  3. Den musst du festhalten, wenn’s zieht – sonst macht der den Abflug!"}]'::jsonb, ''),
  ('im-schuitaschdickl-san-no-a-poa-krischpaln-drin-de-miass-ma-beim-parian-wegtuan', 'Im Schuitaschdickl san no a poa Krischpaln drin - de miass ma beim Parian wegtuan!', '', '', '', 'Wiener Fleischhauer-Slang', 'Im Schulterstück sind noch ein paar Krisperln drin – die müssen wir beim Parieren wegtun!', '[{"kategorie": "wörtlich", "text": "\"Im Schulterstück sind noch ein paar kleine Knorpelstücke drin – die müssen wir beim Parieren sauber entfernen!\"  2. Im Schulterstück befinden sich noch kleinere Knorpelpartien – die sind beim Parieren vollständig zu entfernen!  3. Das Schulterstück enthält noch Knorpelgewebe – bitte beim Parieren sauber auslösen!"}]'::jsonb, ''),
  ('des-krischpal-muassd-aum-zaun-aubindn-sunst-fliagda-da-davoo', 'Des Krischpal muassd aum Zaun aubindn, sunst fliagda da davoo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieses Krischperl musst du am Zaun anbinden, sonst fliegt er dir davon!', '[{"kategorie": "wörtlich", "text": "\"Diesen Hungerhaken musst du am Zaun anbinden, sonst fliegt er dir davon!\"  2. So dünn wie der ist, brauchst du Gewichte an den Füßen, sonst hebt er ab!  3. Den musst du festhalten, wenn’s zieht – sonst macht der den Abflug!"}]'::jsonb, ''),
  ('des-bia-rinnd-do-kriaglweis', 'Des Bia rinnd do kriaglweis!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Das Bier rinnt hier krügelweise!', '[{"kategorie": "wörtlich", "text": "\"Das Bier rinnt hier Krügel für Krügel!\"  2. Das Bier rinnt hier kübelweise!  3. Das Bier fließt hier wie aus Eimern!  4. Das Bier fließt hier in rauen Mengen!"}]'::jsonb, ''),
  ('de-haum-kane-moossglaesa-des-bia-gibds-do-nua-kriaglweis', 'De haum kane Moossgläsa - des Bia gibds do nua kriaglweis!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die haben keine Maßgläser - das Bier gibt''s da nur krügelweise!', '[{"kategorie": "wörtlich", "text": "\"Hier gibt''s Bier nur krügelweise - Maßgläser kannst vergessen!\"  2. Die haben hier keine Maßkrüge, sondern \"Krügerln\" - so wie''s sich in Wien gehört!  3. Maß ist was für Touristen – hier trinkt man aus’m Krügel, und das mit Haltung!"}]'::jsonb, ''),
  ('heit-hods-40-kriagln-im-schottn', 'Heit hods 40 Kriagln im Schottn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Heut'' hat es 40 Krügel im Schatten!', '[{"kategorie": "wörtlich", "text": "\"Heute hat es 40 Halbe im Schatten!\"  2. Heut'' hat es 40 Grad im Schatten!  3. Heut'' hat es 20 Maß im Schatten!"}]'::jsonb, ''),
  ('herr-ober-bringans-ma-no-a-kriagl', 'Herr Ober, bringans ma no a Kriagl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Herr Ober, bringen Sie mir noch ein Krügerl!', '[{"kategorie": "wörtlich", "text": "\"Herr Oberkellner, bringen Sie mir bitte noch ein großes Bier!\"  2. Herr Ober, ich glaub, mein Glas ist undicht – bringen Sie mir noch eine Halbe!  3. Herr Ober, noch ein großes Bier, bitte!"}]'::jsonb, ''),
  ('fiad-habsbuaga-woan-de-kuruzzn-roeboeoen-fia-vueue-ungan-owa-feiheitskaempfa', 'Fiad Habsbuaga woan de Kuruzzn Röböön, fia vüü Ungan owa Feiheitskämpfa!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Für die Habsburger waren die Kuruzzen Rebellen, für viele Ungarn aber Freiheitskämpfer!', '[{"kategorie": "wörtlich", "text": "\"Die Habsburger sahen in den Kuruzzen Rebellen, viele Ungarn jedoch Freiheitskämpfer!\"  2. Während die Habsburger die Kuruzzen als Aufständische betrachteten, galten sie den Ungarn vielfach als Helden!  3. Für Wien waren die Kuruzzen eine Plage, für viele Ungarn ein Segen!"}]'::jsonb, ''),
  ('kruzifix-no-amoi', 'Kruzifix no amoi!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Kruzifix noch einmal!', '[{"kategorie": "", "text": "\"Verdammt und zugenäht!\"  3. \"Verflixt noch mal!\"  4. \"Himmelherrgott noch mal!\""}]'::jsonb, ''),
  ('de-klowasse-is-oaschzaach-host-de-ausn-baumoakd', 'De Klowasse is oaschzaach - host de ausn Baumoakd?', '', '', '', 'Wiener Würstelstandjargon', 'Die Klobasse ist arschzäh - hast du die aus’m Baumarkt?', '[{"kategorie": "wörtlich", "text": "Die Klobasse ist so zäh wie ein fetter Arsch  – hast du die vom Baumarkt?  2. Die Klobasse ist so zäh wie eine Schuhsohle - hast du die beim Schuster statt beim Fleischer gekauft?  3. Die Klobasse ist zäh wie ein Autoreifen – hast du die von der Tankstelle?"}]'::jsonb, ''),
  ('de-blonde-kiiwaed-jaegamaasta-wia-aundare-leitungswossa', 'De Blonde kiiwäd Jägamaasta wia aundare Leitungswossa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Blonde kübelt Jägermeister wie andere Leitungswasser!', '[{"kategorie": "wörtlich", "text": "\"Die Blonde kippt Jägermeister weg wie andere Leitungswasser!\"  2. Die Blonde schüttet Jägermeister in sich hinein wie andere Leute Leitungswasser!  3. Die Blonde säuft Jägermeister, als wär’s Multivitaminsaft!"}]'::jsonb, ''),
  ('i-hob-de-gaunze-nocht-kiiwaed-wiara-lebendigs-speibsackal', 'I hob de gaunze Nocht kiiwäd wiara lebendigs Speibsackal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich habe die ganze Nacht gekübelt wie ein lebendiges Speibsackerl!', '[{"kategorie": "wörtlich", "text": "\"Ich hab’ die ganze Nacht gekotzt, als wär’ ich ‘ne lebende Kotztüte!\"  2. Ich hab’ die ganze Nacht erbrochen, als gäb''s kein Morgen!  3. Letzte Nacht war ich ‘ne wandelnde Kotzmaschine und hab mich leergekotzt bis zum letzten Tropfen!"}]'::jsonb, ''),
  ('des-is-zum-kiiwaen', 'Des is zum Kiiwän!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist zum Kübeln!', '[{"kategorie": "wörtlich", "text": "\"Das gehört direkt in den Mülleimer – mit Deckel drauf!\"  2. Das kannst du in die Tonne kippen!  3. Das kannst du in den Abfall entsorgen!  4. Das kannst du gleich ins Klo kippen!"}]'::jsonb, ''),
  ('mit-dem-kiiwae-wiast-ned-weit-kumma', 'Mit dem Kiiwä wiast ned weit kumma!', '', '', '', 'Wiener Mechaniker-Slang', 'Mit diesem Kübel wirst du nicht weit kommen!', '[{"kategorie": "wörtlich", "text": "\"Mit dieser Klapperkiste wirst du nicht weit kommen!\"  2. Mit dieser Rostlaube kommst du keinen Meter weit!  3. Mit dieser Karre kommst du nicht einmal bis zur nächsten Tankstelle!"}]'::jsonb, ''),
  ('es-schitt-wiaraus-kiiwaen', 'Es schitt wiaraus Kiiwän!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Es schüttet wie aus Kübeln', '[{"kategorie": "wörtlich", "text": "\"Es gießt wie aus Eimern\""}, {"kategorie": "", "text": "Es regnet wie aus allen Rohren!  3. Es schüttet wie aus [[Schaffeln]]!  4. Es regnet [[Schusterbuben]]!"}]'::jsonb, ''),
  ('waunn-mei-oida-kochd-schaud-d-kuchl-noachhar-aus-wiara-schlochtfoeoed', 'Waunn mei Oida kochd, schaud d''Kuchl noachhar aus wiara Schlochtfööd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn mein Alter kocht, schaut die Küche nachher aus wie ein Schlachtfeld!', '[{"kategorie": "wörtlich", "text": "\"Wenn mein Mann kocht, sieht die Küche nachher aus wie nach ''ner Explosion!\"  2. Kochen kann mein Alter – aber nachher sieht''s in der Küche aus, als hätt'' ''ne Bombe eingeschlagen!  3. Mein Alter kocht wie ein Terminator - jedes Mal, wenn er am Herd steht, mutiert die Küche zum Trümmerhaufen!"}]'::jsonb, ''),
  ('in-unsara-kantin-regiad-da-kuchlbaea-wea-sis-mit-dera-auleegd-isst-aum-end-koid', 'In unsara Kantin regiad da Kuchlbäa - wea sis mit dera auleegd, isst aum End koid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'In unserer Kantine regiert der Kuchlbär – wer sich''s mit ihr anlegt, isst am Ende kalt!', '[{"kategorie": "wörtlich", "text": "\"In der Kantine hat die Küchenchefin das Sagen – wer sich''s mit ihr anlegt, kriegt kalte Reste zu essen!\"  2. Unser [[Küchendragoner]] regiert die Küche wie ein Feldwebel – wer meckert, isst kalt!  3. Wenn du Stress mit der Kantinenqueen hast, landest du bei den Tiefkühlresten!"}]'::jsonb, ''),
  ('kuchldeitsch-klingt-wiara-kochrezept-a-bissl-deitsch-a-schuss-beemisch-und-dazua-a-muadstrumm-gschraa', 'Kuchldeitsch klingt wiara Kochrezept: a bissl Deitsch, a Schuss Beemisch, und dazua a muadstrumm Gschraa!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Kuchldeutsch klingt wie ein Kochrezept: ein bisschen Deutsch, ein Schuss Böhmisch, und dazu ein mörderisch lautes Geschrei!', '[{"kategorie": "wörtlich", "text": "\"Kuchldeutsch klingt wie ein Rezept: ein bisschen Deutsch, ein Schuss Böhmisch, und dazu ordentlich Geschrei!\"  2. Kuchldeutsch klingt, als hätte man Deutsch und Böhmisch in den Mixer geworfen – und ihn auf Turbolautstärke gestellt!  3. Wenn Kuchldeutsch erklingt, ist das wie Gulasch für die Ohren – ein bisschen Deutsch, ein Hauch Tschechisch und das Ganze deftig, laut und durcheinander!"}]'::jsonb, ''),
  ('dea-dillo-hod-des-kuchlkastl-so-tiaf-montiad-dass-i-ma-schoo-zigmoi-de-bian-aughaud-hob', 'Dea Dillo hod des Kuchlkastl so tiaf montiad, dass I ma schoo zigmoi de Bian aughaud hob!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Dillo hat das Küchenkästchen so tief montiert, dass ich mir schon zigmal die Birne angehaut hab!', '[{"kategorie": "wörtlich", "text": "\"Der Depp hat das Küchenkästchen so tief hingeschraubt, dass ich mir schon zigmal die Rübe daran angeschlagen habe!\"  2. Der Trottel hat den Küchenschrank so tief festgedübelt, dass ich mir zigmal den Schädel blutig geknallt hab!  3. Das Küchenkastl wurde von dem Blödmann viel zu tief montiert - wenn ich mir noch einmal die Rübe dran stoß, reiß ich es eigenhändig raus!"}]'::jsonb, ''),
  ('seit-da-neiche-lealing-im-haus-is-kreista-wiara-kuchltrabant-planlos-uman-head', 'Seit da neiche Lealing im Haus is, kreista wiara Kuchltrabant planlos uman Head!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Seit der neue Lehrling im Haus ist, kreist er wie ein Küchentrabant planlos um den Herd!', '[{"kategorie": "wörtlich", "text": "\"Seit der neue Lehrling da ist, dreht er wie ein Küchentrabant planlose Ehrenrunden um den Herd!\"  2. Der neue Lehrling geistert um den Herd wie ein Küchentrabant - immer da, und immer im Weg!  3. Seitdem der Lehrling da ist, gurkt er wie ein verwirrter Pfannengeist um den Herd!"}]'::jsonb, ''),
  ('da-neiche-kuchlschlapfn-schluafd-mea-duachd-kuchl-ois-dass-hackld', 'Da neiche Kuchlschlapfn schluafd mea duachd Kuchl ois dass hackld!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der neue Küchenschlapfen schlurft mehr durch die Küche, als dass sie hackelt!', '[{"kategorie": "wörtlich", "text": "\"Die neue Küchenhilfskraft schlurft mehr durch die Küche, als dass sie arbeitet!\"  2. Die neue Küchentrulla schleicht mehr herum, als dass sie den Kochlöffel schwingt!  3. Die neue Küchenhilfe wandelt mehr zwischen den Töpfen, als dass sie sie benutzt!"}]'::jsonb, ''),
  ('a-seviatraumpae-is-no-aeaga-ois-a-kuchlschlapfn-waeu-de-muassd-direkt-aum-tisch-eatroong', 'A Seviatraumpä is no äaga ois a Kuchlschlapfn - wäu de muassd direkt aum Tisch eatroong!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Serviertrampel ist noch ärger als ein Küchenschlapfen - weil die musst du direkt am Tisch ertragen!', '[{"kategorie": "wörtlich", "text": "\"Ein Servierluder ist noch ärger als eine Küchentrulla - weil Erstere musst du direkt am Tisch ertragen!\"  2. Eine Servierschnepfe ist noch schlimmer als eine Küchenhexe – weil mit der musst du am Tisch leiden!  3. Eine Servierkröte erträgt man noch weniger als eine Kochtrulla – weil Erstere steht dir direkt vor der Nase!"}]'::jsonb, ''),
  ('ned-nua-dass-ned-kochn-kau-haengda-dea-kuchltraumpae-aa-noo-a-goschn-au-waunnsd-di-iwas-essn-beschweasd', 'Ned nua, dass ned kochn kau, hängda dea Kuchltraumpä aa noo a Goschn au, waunnsd di iwas Essn beschweasd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nicht nur, dass sie nicht kochen kann, hängt dir dieser Küchentrampel auch noch eine Goschen an, wenn du dich übers Essen beschwerst!', '[{"kategorie": "wörtlich", "text": "\"Nicht nur, dass sie nicht kochen kann, die Küchentrulla fährt dich auch noch an, wenn du dich übers Essen beschwerst!\"  2. Die Herd-Hexe bringt nix Gescheites zusammen und schnauzt dich dann auch noch an, wenn du dich übers Essen beschwerst!  3. Nicht nur, dass sie nix auf die Reihe kriegt - dieses Küchenluder hängt dir obendrein auch noch eine freche Goschen an, wenn du was Schlechtes über ihr Essen sagst!"}]'::jsonb, ''),
  ('de-deppade-kuchlschnepfn-hod-scho-wiida-es-soiz-min-zucka-vawechsld', 'De deppade Kuchlschnepfn hod scho wiida es Soiz min Zucka vawechsld!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die depperte Küchenschnepfe hat schon wieder das Salz mit''m Zucker verwechselt!', '[{"kategorie": "wörtlich", "text": "\"Die blöde Küchentrulla hat schon wieder Zucker statt Salz ins Essen getan!\"  2. Die saudumme Küchenhilfe hat schon wieder Zucker statt Salz in die Suppe gekippt!  3. Die Küchenhenne glaubt, sie ist Chefköchin – dabei kippt sie Zucker statt Salz aufs Steak!"}]'::jsonb, ''),
  ('a-seviaschnepfn-is-no-aeaga-ois-a-kuchlschlapfn-waeu-de-muassd-direkt-aum-tisch-eatroong', 'A Seviaschnepfn is no äaga ois a Kuchlschlapfn - wäu de muassd direkt aum Tisch eatroong!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Eine Servierschnepfe ist noch ärger als ein Küchenschlapfen - weil die musst du direkt am Tisch ertragen!', '[{"kategorie": "wörtlich", "text": "\"Eine Servierschnepfe ist noch schlimmer als eine Küchenhexe – weil mit der musst du am Tisch leiden!\"  2. Ein Servierluder ist noch ärger als eine Küchentrulla - weil Erstere musst du direkt am Tisch ertragen!  3. Eine Servierkröte erträgt man noch weniger als eine Kochtrulla – weil Erstere steht dir direkt vor der Nase!"}]'::jsonb, ''),
  ('tua-ma-kuudan-und-ned-suudan', 'Tua ma kuudan und ned suudan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Tun wir kudern und nicht sudern!', '[{"kategorie": "wörtlich", "text": "\"Lasst uns lachen, statt zu meckern!\"  2. Lachen wir, anstatt uns zu klagen!  3. Lachen statt Motzen!"}]'::jsonb, ''),
  ('de-drei-kuudan-san-a-echte-kreischbrigaadn-waunn-de-zsaummkumman-heast-schdundlaung-a-wueuede-kakophonii-aus-kichan-schnoodan-und-gackan', 'De drei Kuudan san a echte Kreischbrigaadn - waunn de zsaummkumman, heast schdundlaung a wüüde Kakophonii aus Kichan, Schnoodan und Gackan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die drei Kudern sind eine echte Kreischbrigade - wenn die zusammenkommen, hörst du stundenlang eine wilde Kakophonie aus Kichern, Schnattern und Gackern!', '[{"kategorie": "wörtlich", "text": "\"Die drei Lachtrullas sind zusammen ein richtiges Giggelgeschwader – sobald die loslegen, hörst du stundenlang eine wilde Kakophonie aus Kichern, Schnattern und Gackern!\"  2. Zusammen sind die drei Kudern ein Kichertrio deluxe –  ein wildes, endloses Durcheinander aus Gackern, Schnattern und Lachen!  3. Die drei Kudern sind ein wahres Gackerkommando – stundenlang hörst du nur wildes Gelächter, Gegiggel und Geschnatter!"}]'::jsonb, ''),
  ('an-kuudara-mochn', 'an Kuudara mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Kuderer machen', '[{"kategorie": "wörtlich", "text": "\"einen Gluckser machen\""}, {"kategorie": "", "text": "\"einen Kicherer rauslassen\""}, {"kategorie": "", "text": "\"einen Quiekser machen\""}, {"kategorie": "", "text": "\"einen glucksenden Lacher von sich geben\""}, {"kategorie": "", "text": "\"einen Lach-Rülpser rauslassen\""}, {"kategorie": "", "text": "\"ein glucksendes Kichern ausstoßen\""}]'::jsonb, 'Unsa Schääfin hod imma a eanstes Gsichd auf - owa wia da Vuaoaweita bei da Weinochtsfeia auf amoi in da Untagattn vua ia gschdaundn is, hod söbst si an Kuudara gmochd!'),
  ('unsa-schaeaefin-hod-imma-a-eanstes-gsichd-auf-owa-wia-da-vuaoaweita-bei-da-weinochtsfeia-auf-amoi-in-da-untagattn-vua-ia-gschdaundn-is-hod-soebst-si-an-kuudara-gmochd', 'Unsa Schääfin hod imma a eanstes Gsichd auf - owa wia da Vuaoaweita bei da Weinochtsfeia auf amoi in da Untagattn vua ia gschdaundn is, hod söbst si an Kuudara gmochd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Unsere Chefin hat immer ein ernstes Gesicht auf - aber wie der Vorarbeiter bei der Weihnachtsfeier auf einmal in der Untergatten vor ihr gestanden ist, hat selbst sie einen Kuderer gemacht!', '[{"kategorie": "wörtlich", "text": "\"Unsere Chefin hat immer ein ernstes Gesicht aufgesetzt - aber als der Vorarbeiter bei der Weihnachtsfeier plötzlich in Unterhosen vor ihr stand, hat selbst sie einen glucksenden Lacher rausgelassen!\"  2. Unsere Chefin läuft sonst mit einer Grabesmiene herum – aber als der Vorarbeiter bei der Weihnachtsfeier plötzlich in Unterhosen vor ihr stand, musste selbst sie glucksend loskichern!  3. Unsere Chefin wirkt immer steif und streng – doch als der Vorarbeiter bei der Weihnachtsfeier in Unterhosen auf sie zutorkelte, ist selbst ihr ein Kicherer rausgerutscht!"}]'::jsonb, ''),
  ('wia-in-wean-soong-zu-de-flittawochn-aa-kuudawochn-waeu-ma-in-dera-zeit-vueue-kuudan-oiso-lochn-kichan-jux-mochn-tuad', 'Wia in Wean soong zu de Flittawochn aa ''Kuudawochn'', wäu ma in dera Zeit vüü ''kuudan'' - oiso lochn, kichan, Jux mochn - tuad', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wir in Wien sagen zu den Flitterwochen auch ''Kuderwochen'', weil man in dieser Zeit viel kudern - also lachen, kichern, Jux machen - tut!', '[{"kategorie": "wörtlich", "text": "\"Bei uns in Wien heißen die Flitterwochen gern auch ''Kuderwochen'', weil man dabei viel kudert – also lacht, kichert und Schabernack treibt!\"  2. In Wien nennen wir die Flitterwochen scherzhaft auch ''Kuderwochen'' – weil''s da viel zu lachen, kichern und spaßen gibt!  3. Flitterwochen heißen bei uns in Wien auch ''Kuderwochen'', weil in dieser Zeit viel gekichert, gelacht und herumgealbert wird!"}]'::jsonb, ''),
  ('zeaschd-kneedlakademii-daunn-glei-hochzeit-da-lebenslauf-von-an-echtn-vuaschdodt-waawal', 'Zeaschd Kneedlakademii, daunn glei Hochzeit - da Lebenslauf von an echtn Vuaschdodt-Waawal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Zuerst Knödelakademie, dann gleich Hochzeit – der Lebenslauf von einem echten Vorstadtweibchen!', '[{"kategorie": "wörtlich", "text": "\"Zuerst Hauswirtschaftsschule, dann gleich Hochzeit – der Lebenslauf einer echten Vorstadt-Barbie!\"  2. Erst Mädchenoberschule, dann gleich in Weiß vor den Altar – der klassische Karriereweg einer echten Vorstadt-Barbie!  3. Erst acht Semester Knödelakademie, dann lebenslänglich Ehemann – Vorstadtträume deluxe!"}]'::jsonb, ''),
  ('zeaschd-kochlefflakademii-daunn-glei-hochzeit-da-lebenslauf-von-an-echtn-vuaschdodt-waawal', 'Zeaschd Kochlefflakademii, daunn glei Hochzeit - da Lebenslauf von an echtn Vuaschdodt-Waawal!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zuerst Kochlöffelakademie, dann gleich Hochzeit – der Lebenslauf von einem echten Vorstadtweibchen!', '[{"kategorie": "wörtlich", "text": "\"Zuerst Hauswirtschaftsschule, dann gleich Hochzeit – der Lebenslauf einer echten Vorstadt-Barbie!\"  2. Erst Mädchenoberschule, dann gleich in Weiß vor den Altar – der klassische Karriereweg einer echten Vorstadt-Barbie!  3. Erst acht Semester Kochlöffelakademie, dann lebenslänglich Ehemann – Vorstadtträume deluxe!"}]'::jsonb, ''),
  ('in-wean-suudad-ma-ned-waeu-wos-is-ma-suudad-waeu-ma-leebd', 'In Wean suudad ma ned, wäu wos is - ma suudad, wäu ma leebd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'In Wien sudert man nicht, weil was ist – man sudert, weil man lebt!', '[{"kategorie": "wörtlich", "text": "\"In Wien jammert man nicht, weil irgendetwas ist – man jammert, weil es zum ''Wienersein'' dazugehört!\"  2. In Wien motzt man nicht wegen ein bisschen Drama – man motzt aus Prinzip!  3. Wenn der Wiener aufhört zu sudern, ist entweder Sonntag oder er is tot!"}]'::jsonb, ''),
  ('de-suudarei-geed-ma-aum-oasch', 'De Suudarei geed ma aum Oasch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Suderei geht mir am Arsch!', '[{"kategorie": "wörtlich", "text": "\"Das ständige Gejammer geht mir auf die Nerven!\"  2. \"Ich kann diese [[Raunzerei]] nicht mehr ertragen!\"  3. \"Dieses ständige Lamentieren geht mir auf den Geist!\""}]'::jsonb, ''),
  ('des-gsuudare-geed-ma-aum-oasch', 'Des Gsuudare geed ma aum Oasch!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Das Gesudere geht mir am Arsch!', '[{"kategorie": "wörtlich", "text": "\"Das ständige Gejammer geht mir auf die Nerven!\"  2. \"Ich kann diese [[Raunzerei]] nicht mehr ertragen!\"  3. \"Dieses ständige Lamentieren geht mir auf den Geist!\""}]'::jsonb, ''),
  ('sei-ewiche-grantlarei-geed-ma-aum-zaaga-ned-amoi-da-hund-mog-eam-mea', 'Sei ewiche Grantlarei geed ma aum Zaaga - ned amoi da Hund mog eam mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seine ewige Grantlerei geht mir auf den Zeiger - nicht einmal der Hund mag ihn mehr!', '[{"kategorie": "wörtlich", "text": "\"Sein ewiges Gegrantel geht mir auf die Nerven - nicht einmal der Hund mag ihn mehr!\"  2. Sein endloses Gesudere macht mich narrisch – selbst der Hund streikt schon!  3. Sein unaufhörliches Geraunze treibt mich in den Wahnsinn – nicht einmal der Hund hält''s mit ihm aus!"}]'::jsonb, ''),
  ('ois-kinda-hauma-in-gugaruz-draussd-im-goatn-iwan-feia-greesd-und-daunn-aa-glei-vaputzd', 'Ois Kinda hauma in Gugaruz draussd im Goatn iwan Feia greesd und daunn aa glei vaputzd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als Kinder haben wir den Kukuruz draußen im Garten über dem Feuer geröstet und dann auch gleich verputzt!', '[{"kategorie": "wörtlich", "text": "\"Als Kinder haben wir uns frische Maiskolben draußen im Garten überm Feuer gebraten und dann auch gleich direkt verputzt!\"  2. Als wir klein waren, rösteten wir Maiskolben über dem Feuer und genossen sie im Freien – frisch und duftend!  3. Das waren die besten Sommerabende: Wir Kinder rösteten Kukuruz am Lagerfeuer im Garten und aßen ihn noch heiß!"}]'::jsonb, ''),
  ('waunn-i-an-gugarzkoim-schnabulia-schau-i-aus-wiara-hendl-beim-keandlpickn', 'Waunn I an Gugarzkoim schnabulia, schau I aus wiara Hendl beim Keandlpickn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich einen Kukuruzkolben schnabuliere, sehe ich aus wie ein Huhn beim Körnerpicken!', '[{"kategorie": "wörtlich", "text": "\"Beim Knabbern an einem Kukuruzkolben komm ich mir vor wie ein Huhn, das Körner pickt!\"  2. Wenn ich an einem Maiskolben knabbere, sehe ich aus wie ein hungriges Huhn auf Körnersuche!  3. Ich seh aus, als wär ich ein Huhn im Fressrausch, wenn ich so ''nen Maiskolben schnabuliere!"}]'::jsonb, 'Ois Kinda hauma in Gugaruz draussd im Goatn iwan Feia greesd und daunn aa glei vaputzd!'),
  ('maunchmoi-is-a-voigschmiiads-kaaspapial-kreativa-ois-jeede-duachstrukturiade-planung', 'Maunchmoi is a voigschmiiads Kaaspapial kreativa ois jeede duachstrukturiade Planung!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Manchmal ist ein vollgeschmierter Kaszettel kreativer als jede strukturierte Planung!', '[{"kategorie": "wörtlich", "text": "\"Manchmal ist ein chaotischer Schmierzettel kreativer als jede strukturierte Planung!\"  2. Manchmal steckt in einem vollgekritzelten Schmierblatt mehr Kreativität als in ’ner Excel-Tabelle!  3. So ein zerfledderter Notizzettel kann mehr bringen als jeder schön designte Projektplan!"}]'::jsonb, ''),
  ('i-hob-da-ollas-auf-aan-kaaszeedl-aufgschriebm-damit-dei-schimplads-hian-ned-wiida-wos-vagissd', 'I hob da ollas auf aan Kaaszeedl aufgschriebm - damit dei schimplads Hian ned wiida wos vagissd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab dir alles auf einen Kaszettel aufgeschrieben - damit dein verschimmeltes Hirn nicht wieder was vergisst!', '[{"kategorie": "wörtlich", "text": "\"Ich hab dir alles auf einen Schmierzettel aufgeschrieben - damit dein vergammeltes Hirn nicht wieder was vergisst!\"  2. Ich hab dir den ganzen Kram auf ''nen Schmierzettel gekritzelt – sonst vergisst dein Rosthirn wieder alles!  3. Hab dir alles auf ''nem Schmierzettel notiert – bevor du wieder behauptest, du hättest von nix gewusst!"}]'::jsonb, ''),
  ('kakauschdich-klingd-heazich-is-owa-nix-fia-aufaenga', 'Kakauschdich klingd heazich - is owa nix fia Aufänga!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Kakaostich klingt herzig – ist aber nichts für Anfänger!', '[{"kategorie": "wörtlich", "text": "\"Kakaostich klingt niedlich – ist aber nichts für Anfänger!  2. Kakaostich hört sich harmlos an - heißt aber Analverkehr!\"  3. ''Kakaostich'' heißt ''anale Penetration'' - also definitiv eine Nummer für Fortgeschrittene!\""}]'::jsonb, ''),
  ('so-katolisch-wia-ea-tuad-isa-im-leebm-ned', 'So katolisch wia ea tuad, isa im Leebm ned!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'So katholisch, wie er tut, ist er im Leben nicht!', '[{"kategorie": "wörtlich", "text": "\"So kreuzbrav, wie er sich gibt, ist er überhaupt nicht!\"  2. Er tut auf grundanständig, aber das ist er in Wahrheit nicht!  3. So heilig, wie er daherkommt, ist er mit Sicherheit nicht!"}]'::jsonb, ''),
  ('katolisch-grinsn', 'katolisch grinsn', '', '', '', 'Wiener Gaunersprache', 'katholisch grinsen', '[{"kategorie": "wörtlich", "text": "\"auf die katholische Art grinsen\""}, {"kategorie": "", "text": "\"hämisch grinsen\""}, {"kategorie": "", "text": "\"schadenfroh lächeln\""}, {"kategorie": "", "text": "\"boshaft den Mund verziehen\""}, {"kategorie": "", "text": "\"scheinheilig grinsen\""}]'::jsonb, ''),
  ('imma-waunna-liagd-setzda-sei-katolischs-grinsn-auf-fromm-owa-valoong', 'Imma waunna liagd, setzda sei katolischs Grinsn auf - fromm, owa valoong!', '', '', '', 'Wiener Gaunersprache', 'Immer wenn er lügt, setzt er sein katholische Grinsen auf – fromm, aber verlogen!', '[{"kategorie": "wörtlich", "text": "\"Immer wenn er lügt, setzt er dieses scheinheilige Grinsen auf – kreuzbrav nach außen, aber verlogen im Kern!\"  2. Wenn er lügt, hat er dieses Ministrantenlächeln – unschuldig im Schein, verdorben im Kern!  3. Immer wenn er die Wahrheit verbiegt, trägt er sein Frömmlergrinsen spazieren – er tut auf heilig, aber man riecht den Teufel dahinter!"}]'::jsonb, 'katolisch grinsn'),
  ('wem-katolisch-mochn', 'wem katolisch mochn', '', '', '', 'Wiener Gaunersprache', 'jemanden katholisch machen', '[{"kategorie": "wörtlich", "text": "\"jemanden kreuzbrav machen\""}, {"kategorie": "", "text": "\"jemanden ins Gebet nehmen\""}, {"kategorie": "fig.", "text": "\"jemanden zur Schnecke machen\""}, {"kategorie": "", "text": "\"jemanden auf dem Beichtstuhl grillen\""}, {"kategorie": "", "text": "\"jemandem die Leviten lesen\""}, {"kategorie": "", "text": "\"jemandem die Hölle heiß machen\""}, {"kategorie": "", "text": "\"jemandem den Kopf waschen\""}, {"kategorie": "", "text": "\"jemandem den Arsch aufreißen\""}, {"kategorie": "", "text": "\"jemanden brutal zusammenstauchen\""}]'::jsonb, 'Da Trääna hod sei Maunnschofd katolisch gmochd - aufmuckn traud si jetzt kaana mea!'),
  ('da-traeaena-hod-sei-maunnschofd-katolisch-gmochd-aufmuckn-traud-si-jetzt-kaana-mea', 'Da Trääna hod sei Maunnschofd katolisch gmochd - aufmuckn traud si jetzt kaana mea!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Trainer hat seine Mannschaft katholisch gemacht – aufmucken traut sich jetzt keiner mehr!', '[{"kategorie": "wörtlich", "text": "\"Der Trainer hat seine Mannschaft kreuzbrav gemacht – jetzt ist Ruhe im Karton!\"  2. Der Coach hat seiner Mannschaft den Arsch aufgerissen - jetzt sagt niemand mehr ein Wort!  3. Der Trainer hat sie alle in der Kabine brutal zusammengestaucht – jetzt wagt keiner mehr aus Mannschaft, auch nur einen Pieps von sich zu geben!"}]'::jsonb, 'wem katolisch mochn'),
  ('si-hod-uns-schee-katolisch-gmochd', 'Si hod uns schee katolisch gmochd!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Sie hat uns schön katholisch gemacht!', '[{"kategorie": "wörtlich", "text": "\"Sie hat uns ordentlich zur Schnecke gemacht!  2. \"Sie hat uns so richtig die Leviten gelesen – aber vom Feinsten!\"  3. \"Sie hat uns den Kopf gewaschen - und wie!\"  4. \"Sie hat uns ziemlich unchristlich [[zusammengestaucht]]!\"  5. \"Sie hat uns so richtig den Arsch aufgerissen!\"  6. Sie hat uns die Hölle heiß gemacht!"}]'::jsonb, ''),
  ('den-weama-aa-no-katolisch-mochn', 'Den weama aa no katolisch mochn!', '', '', '', 'Wiener Gaunersprache', 'Den werden wir auch noch katholisch machen!', '[{"kategorie": "wörtlich", "text": "\"Den werden wir auch noch kreuzbrav machen!\"  2. \"Den kriegen wir auch noch klein!\"  3. \"Den drehen wir auch noch durch die Mangel!\"  4. \"Den nehmen wir auch noch ins Gebet!\""}]'::jsonb, ''),
  ('katolisch-wean', 'katolisch wean', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'katholisch werden', '[{"kategorie": "wörtlich", "text": "\"kreuzbrav werden\""}, {"kategorie": "", "text": "\"lammfromm werden\""}, {"kategorie": "", "text": "\"handzahm werden\""}, {"kategorie": "", "text": "\"brav wie ein Engel werden\""}, {"kategorie": "", "text": "\"keinen Mucks mehr von sich geben\""}]'::jsonb, ''),
  ('i-hau-darane-owe-dassd-katolisch-wiast', 'I hau darane owe, dassd katolisch wiast!', '', '', '', 'Wiener Gaunersprache', 'Ich hau dir eine runter, dass du katholisch wirst!', '[{"kategorie": "", "text": "wörtlich): \"Ich hau dir eine runter, auf dass du katholisch wirst!\"  2. \"Ich hau dir eine Fresse, bis du klein und kreuzbrav wirst!\"  3. \"Ich hau dir eine aufs Maul, dass du endlich parierst!\"  4. \"Ich knall dir eine, dass du keinen Mucks mehr machst!\"  5. \"Ich klatsch dir eine, dass dir Hören und Sehen vergeht!\""}]'::jsonb, 'katolisch wean'),
  ('katolisch-zuagee', 'katolisch zuagee', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'katholisch zugehen', '[{"kategorie": "wörtlich", "text": "\"sittsam zugehen\""}, {"kategorie": "", "text": "\"tugendhaft vonstatten gehen\""}, {"kategorie": "", "text": "\"mit rechten Dingen zugehen\""}]'::jsonb, ''),
  ('do-geeds-ned-grod-katolisch-zua', 'Do geeds ned grod katolisch zua!', '', '', '', 'Wiener Gaunersprache', 'Da geht es nicht gerade katholisch zu!', '[{"kategorie": "wörtlich", "text": "\"Da geht es nicht gerade sittsam zu!\"  2. \"Da ist einiges nicht im Reinen!\"  3. \"Da laufen irgendwelche krumme Touren!\"  4. \"Da ist etwas nicht ganz [[koscher]]!\""}]'::jsonb, 'katolisch zuagee'),
  ('katolisch-sei', 'katolisch sei', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'katholisch sein', '[{"kategorie": "wörtlich", "text": "\"sittsam sein\""}, {"kategorie": "", "text": "\"tugendhaft sein\""}, {"kategorie": "", "text": "\"kreuzbrav sein\""}]'::jsonb, ''),
  ('dea-is-aa-ned-grod-katolisch', 'Dea is aa ned grod katolisch!', '', '', '', 'Wiener Gaunersprache', 'Der ist auch nicht gerade katholisch', '[{"kategorie": "wörtlich", "text": "\"Der ist auch nicht gerade ein Heiliger!\"  2. \"Der ist auch nicht gerade ein Tugendbold!\"  3. \"Der hat auch nicht unbedingt einen christlichen Charakter!\"  4. \"Der ist auch nicht gerade ein Unschuldsknabe!\""}]'::jsonb, 'katolisch sei'),
  ('katolisch-dreischau', 'katolisch dreischau', '', '', '', 'Wiener Sprüche, die sitzen!', 'katholisch dreinschauen', '[{"kategorie": "wörtlich", "text": "\"eine Unschuldsmiene aufsetzen\""}, {"kategorie": "", "text": "\"die Unschuld vom Lande spielen\""}, {"kategorie": "", "text": "\"eine scheinheilige Fratze ziehen\""}, {"kategorie": "", "text": "\"ein Gesicht wie eine Heiligenstatue machen\""}]'::jsonb, 'Schau ned so katolisch drei, du foische Sau!'),
  ('schau-ned-so-katolisch-drei-du-foische-sau', 'Schau ned so katolisch drei, du foische Sau!', '', '', '', 'Wiener Gaunersprache', 'Schau nicht so katholisch drein, du falsche Sau!', '[{"kategorie": "wörtlich", "text": "\"Schau nicht so scheinheilig drein, du falsches Schwein!\"  2. \"Guck nicht so frömmlerisch, du Heuchlerschwein!\"  3. \"Spar dir das unschuldige Gesicht, du verlogenes Aas!\""}]'::jsonb, 'katolisch dreischau'),
  ('katolischa-ois-da-pobst-sei', 'katolischa ois da Pobst sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'katholischer als der Papst sein', '[{"kategorie": "wörtlich", "text": "\"päpstlicher als der Papst sein\""}, {"kategorie": "", "text": "\"den Moralapostel spielen\""}, {"kategorie": "", "text": "\"strenger als jede Nonne sein\""}]'::jsonb, 'Mei Schwiigamuada is katolischa ois da Pobst - ois hädads de Moral eafundn und wia olle miassdn noch iara Pfeifn taunzn!'),
  ('mei-schwiigamuada-is-katolischa-ois-da-pobst-ois-haedads-de-moral-eafundn-und-wia-olle-miassdn-noch-iara-pfeifn-taunzn', 'Mei Schwiigamuada is katolischa ois da Pobst - ois hädads de Moral eafundn und wia olle miassdn noch iara Pfeifn taunzn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Meine Schwiegermutter ist katholischer als der Papst - als hätte sie die Moral erfunden und wir alle müssten alle nach ihrer Pfiefe tanzen!', '[{"kategorie": "wörtlich", "text": "\"Meine Schwiegermutter ist päpstlicher als der Papst – die glaubt echt, Moral sei ihre Erfindung und wir alle müssten nach ihrer Pfeife tanzen!\"  2. Meine Schwiegermutter ist strenger als jede Nonne – überzeugt, dass sie allein die Moral gepachtet hat und wir nach ihrer Pfeife tanzen müssen!  3. Meine Schwiegermutter gibt sich tugendhafter als die Bibel selbst und kommandiert uns herum, als sei sie Gottes Stellvertreterin!"}]'::jsonb, 'katolischa ois da Pobst sei'),
  ('katolischa-buusn', 'katolischa Buusn', 'der', '', '', 'Echte Wiener Schmähperlen', 'katholischer Busen', '[{"kategorie": "scherzhaft für", "text": "Hängebrust, [[Hängetuttln]], [[Schrotbeutel]], [[Kniaschussduttln]] (bis zum Knie reichende Hängebrust)"}]'::jsonb, 'Waunn si de Oide in da Kiachn niidakniad, liigd ia katolischa Buusn aum Kniabreedl auf!'),
  ('waunn-si-de-oide-in-da-kiachn-niidakniad-liigd-ia-katolischa-buusn-aum-kniabreedl-auf', 'Waunn si de Oide in da Kiachn niidakniad, liigd ia katolischa Buusn aum Kniabreedl auf!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Wenn sich die Alte in der Kirche niederkniet, liegt ihr katholischer Busen auf dem Kniebrettl auf!', '[{"kategorie": "wörtlich", "text": "\"Wenn sich die Alte in der Kirche hinkniet, parkt ihr katholischer Busen direkt auf dem Kniebrett!\"  2. Wenn sich die Alte beim Beten niederkniet, hat ihr Hängebusen Bodenkontakt!  3. Sobald die Alte niederkniet, klatschen ihre Glocken auf''m Kniebrettl auf!"}]'::jsonb, 'katolischa Buusn'),
  ('ia-oida-is-a-katolischa-duach-und-duach-vua-an-jeedn-essn-muass-mit-eam-dahaam-beetn', 'Ia Oida is a Katolischa duach und duach - vua an jeedn Essn muass mit eam dahaam beetn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Ihr Alter ist ein Katholischer durch und durch - vor jedem Essen muss sie daheim mit ihm beten!', '[{"kategorie": "wörtlich", "text": "\"Ihr Alter ist ein streng gläubiger Katholik – vor jedem Essen muss sie mit ihm zu Hause beten!\"  2. Ihr Mann ist ein strammer Kathole – nicht mal die Suppe darf ohne Gebet angerührt werden!  3. Ihr Ehemann ist praktizierender Katholik durch und durch – da geht nichts ohne Beten vor dem Essen!"}]'::jsonb, ''),
  ('pass-auf-den-katolischn-do-auf-noch-aussn-schbueueda-an-haeulign-owa-hintnrum-scheissda-di-au', 'Pass auf den Katolischn do auf - noch aussn schbüüda an Häulign, owa hintnrum scheissda di au!', '', '', '', 'Wiener Gaunersprache', 'Pass auf den Katholischen da auf – nach außen spielt er den Heiligen, aber hintenrum scheißt er dich an!', '[{"kategorie": "wörtlich", "text": "\"Pass auf den Katholischen da auf – nach außen macht er den Heiligen, aber hintenrum bescheißt er dich!\"  2. Pass auf den Frömmler da auf – vorne singt er dir ''Halleluja'', und hinten zieht er dich über’n Tisch!  3. Pass auf, das ist ein falscher Fuffziger – gibt den Heiligen, ist aber ein Gauner!"}]'::jsonb, ''),
  ('de-haum-si-a-haus-in-gigarizbootschn-baud-do-bist-so-allaa-do-muassd-dei-echo-soeoewa-griassn', 'De haum si a Haus in Gigarizbootschn baud - do bist so allaa, do muassd dei Echo sööwa griassn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die haben sich ein Haus in Kikerizpatschen gebaut - da bist du so allein, dass du dein Echo selber grüßen musst!', '[{"kategorie": "wörtlich", "text": "\"Die haben sich in der tiefsten Provinz ein Haus hingestellt – da hörst du außer deinem Echo nichts!\"  2. Die sind in so ein abgeschiedenes Kuhkaff gezogen – da sagt dir nur noch die Kuh „Grüß Gott“!  3. Die haben sich in der Einöde ein Haus gebaut – da antwortet dir höchstens noch dein Echo!"}]'::jsonb, ''),
  ('kaan-bock', 'Kaan Bock!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Keinen Bock!', '[{"kategorie": "wörtlich", "text": "\"Keine Lust!\"  2. \"Null Bock!\"  3. \"Bin nicht in Stimmung!\""}]'::jsonb, ''),
  ('i-hob-kaan-bock', 'I hob kaan Bock!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich habe keinen Bock!', '[{"kategorie": "wörtlich", "text": "\"Ich habe keine Lust!\"  2. \"Mir ist nicht danach!\"  3. \"Ich bin nicht in Stimmung!\""}]'::jsonb, ''),
  ('kaan-bock-haum', 'kaan Bock haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'keinen Bock haben', '[{"kategorie": "wörtlich", "text": "\"keine Lust haben\""}, {"kategorie": "", "text": "\"kein Interesse haben\""}, {"kategorie": "", "text": "\"nicht in Stimmung sein\""}]'::jsonb, 'I hob kaan Bock!'),
  ('i-hob-heid-echt-kaan-bock-auf-party-mia-haengd-da-schlecka-no-von-gestan-ausse', 'I hob heid echt kaan Bock auf Party - mia hängd da Schlecka no von gestan ausse!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich habe heut echt keinen Bock auf Party - mir hängt der Schlecker noch von gestern raus!', '[{"kategorie": "wörtlich", "text": "\"Ich habe heut echt keine Lust auf Party - mir hängt die Zunge noch von gestern raus!\"  2. Ich bin heute nicht in Partystimmung - der Kater von gestern hängt mir immer noch nach!  3. Von Party heute will ich gar nichts hören – bin noch komplett platt von gestern!"}]'::jsonb, 'kaan Bock haum'),
  ('kapische', 'Kapische?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Kapische?', '[{"kategorie": "wörtlich", "text": "\"Kapiert?\"  (vom italienischen \"Capisce?\"=\"Kapierst du?\")"}, {"kategorie": "allg.", "text": "\"Verstanden?\"  3. \"Klaro?\"  4. \"Alles klar?\""}]'::jsonb, 'Daschiass eam afoch, kapische?'),
  ('daschiass-eam-afoch-kapische', 'Daschiass eam afoch, kapische?', '', '', '', 'Wiener Gaunersprache', 'Erschieß ihn einfach, kapische?', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Erschieß ihn einfach, kapiert?\"  2. Erschieß ihn einfach, hast du verstanden?  3. Leg ihn einfach um, alles klar?"}]'::jsonb, ''),
  ('klaro', 'Klaro?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Klaro?', '[{"kategorie": "wörtlich", "text": "\"Alles klar?\"  (vom mittelhochdeutschen \"clâr\"=\"klar\")"}, {"kategorie": "", "text": "Verstanden?  3. Kapiert?  4. [[Kapische]]?"}]'::jsonb, ''),
  ('daschiass-eam-afoch-klaro', 'Daschiass eam afoch, klaro?', '', '', '', 'Wiener Gaunersprache', 'Erschieß ihn einfach, klaro?', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Erschieß ihn einfach, alles klar?\"  2. Erschieß ihn einfach, hast du verstanden?  3. Leg ihn einfach um, [[kapische]]?"}]'::jsonb, ''),
  ('ziag-in-bauxal-a-kapuzal-iwan-kopf-waunnsd-aussegeesd', 'Ziag in Bauxal a Kapuzal iwan Kopf, waunnsd aussegeesd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zieh dem Bauxerl ein Kapuzerl über''n Kopf, wenn du rausgehst!', '[{"kategorie": "wörtlich", "text": "\"Zieh dem Baby ein Kapuzerl über, wenn du rausgehst!\"  2. Setz dem Kleinen die Kapuze auf, bevor ihr rausgeht!  3. Mach dem Baby die Kapuze drüber, sonst wird’s ihm kalt!"}]'::jsonb, ''),
  ('si-a-kapuzal-umhaengan', 'si a Kapuzal umhängan', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich ein Kapuzerl umhängen', '[{"kategorie": "wörtlich", "text": "\"sich ein kleines Räuschlein antrinken\""}, {"kategorie": "", "text": "\"sich in Stimmung trinken\""}, {"kategorie": "", "text": "\"sich ein Rauscherl basteln\""}, {"kategorie": "", "text": "\"sich ein Grundrauschen holen\""}, {"kategorie": "", "text": "[[tschechern]], [[schwassn]], [[bippaln]], [[zipfän]]"}]'::jsonb, 'Vasumpfd samma ned - wia haum uns  nua a klaans Kapuzal umghängd!'),
  ('vasumpfd-samma-ned-wia-haum-uns-nua-a-klaans-kapuzal-umghaengd', 'Vasumpfd samma ned - wia haum uns  nua a klaans Kapuzal umghängd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Versumpft sind wir nicht - wir haben uns nur ein kleines Kapuzchen umgehängt!', '[{"kategorie": "wörtlich", "text": "\"Versumpft sind wir nicht - wir haben uns nur ein kleines Räuschlein angetrunken!\"  2. Abgestürzt sind wir nicht – wir haben uns bloß ein kleines Feierabendräuschchen angetrunken!  3. Es war kein Saufgelage – wir haben uns nur ein kleines Grundrauschen gegönnt!"}]'::jsonb, 'si a Kapuzal umhängan'),
  ('den-sei-kotz-is-eeha-a-ausgwochsana-kaumpftiiga-mit-supakroin', 'Den sei Kotz is eeha a ausgwochsana Kaumpftiiga mit Supakroin!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Katze von ihm ist eher ein ausgewachsener Kampftiger mit Superkrallen!', '[{"kategorie": "wörtlich", "text": "\"Seine Katze ist eher ein ausgewachsener Kampftiger mit Krallen aus Stahl!\"  2. Seine Katze ist eher ein Raubtier im Wohnzimmer - sieht harmlos aus, hat aber Krallen aus Stahl!  3. Die Katze von ihm ist kein Stubentiger, das ist eher ein Sibirischer Urtiger mit stahlscharfen Krallen!"}]'::jsonb, ''),
  ('a-faesche-kotz', 'a fäsche Kotz', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine fesche Katz', '[{"kategorie": "wörtlich", "text": "\"ein hübsches Mädchen\""}, {"kategorie": "", "text": "\"ein schnittiges Weiberl\""}, {"kategorie": "", "text": "\"ein hübsches Dirndl\""}, {"kategorie": "", "text": "\"ein heißes Mädel\""}]'::jsonb, 'De Sandra is echt a fäsche Kotz - owa leichd hods mit dera kaana!'),
  ('de-sandra-is-echt-a-faesche-kotz-owa-leichd-hods-mit-dera-kaana', 'De Sandra is echt a fäsche Kotz - owa leichd hods mit dera kaana!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Sandra ist echt eine fesche Katz'' - aber leicht hat''s mit der keiner!', '[{"kategorie": "wörtlich", "text": "\"Die Sandra ist echt ein fesches Mädel – aber leicht tut sich mit ihr keiner!\"  2. Die Sandra ist wirklich ein hübsches Dirndl – aber pflegeleicht ist sie nicht!  3. Die Sandra ist ein bildhübsches Mädchen - – aber sie kann auch ganz schön anstrengend sein!"}]'::jsonb, 'a fäsche Kotz'),
  ('des-ollas-is-fiad-kotz', 'Des ollas is fiad Kotz!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das alles ist für die Katz', '[{"kategorie": "wörtlich", "text": "\"Das ist alles umsonst!\"  2. \"Das ist alles [[für]]''n Hugo!\"  3. \"Das ist alles für die [[Jetti-Tant]]!\"  4. \"Das sind alles nur [[leere]] Kilometer!\""}]'::jsonb, ''),
  ('jaumman-wiad-kotz-im-sock', 'jaumman wiad Kotz im Sock', '', '', '', 'Wiener Sprüche, die sitzen!', 'jammern wie die Katz im Sack', '[{"kategorie": "wörtlich", "text": "\"jammern wie ein Häufchen Elend\""}, {"kategorie": "", "text": "\"quengeln wie ein kleines Kind\""}, {"kategorie": "", "text": "\"heulen wie ein Schlosshund\""}, {"kategorie": "", "text": "\"jaulen wie ein geprügelter Hund\""}]'::jsonb, 'Seita bei da Prüfung duachgrassld is, jaummada wia de Kotz im Sock!'),
  ('seita-bei-da-pruefung-duachgrassld-is-jaummada-wia-de-kotz-im-sock', 'Seita bei da Prüfung duachgrassld is, jaummada wia de Kotz im Sock!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Seit er bei der Prüfung durchgerasselt ist, jammert er wie die Katz'' im Sack!', '[{"kategorie": "wörtlich", "text": "\"Seit er bei der Prüfung durchgefallen ist, jammert er wie die Katz'' im Sack!\"  2. Seit er die Prüfung vergeigt hat, jammert er wie ein geprügelter Hund!  3. Seit er bei der Prüfung eine Bauchlandung hingelegt hat, jammert er, als wär die Welt untergegangen!"}]'::jsonb, 'jaumman wiad Kotz im Sock'),
  ('do-mochd-d-kotz-kaan-buugl', 'Do mochd d''Kotz kaan Buugl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da macht die Katze keinen Buckel!', '[{"kategorie": "wörtlich", "text": "\"Da schlägt keiner die Krallen aus!\"  2. \"Davon geht die Welt nicht unter!\"  3. \"Das ist halb so wild!\"  4. Das schlägt keine Wellen!  5. Da regt sich niemand auf!"}]'::jsonb, 'Zeen Minutn Vaschbätung is grod no okay - do mochd de Kotz kaan Buugl!'),
  ('zeen-minutn-vaschbaetung-is-grod-no-okay-do-mochd-de-kotz-kaan-buugl', 'Zeen Minutn Vaschbätung is grod no okay - do mochd de Kotz kaan Buugl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zehn Minuten Verspätung ist gerade noch okay - da macht die Katze keinen Buckel!', '[{"kategorie": "wörtlich", "text": "\"Zehn Minuten Verspätung sind noch im Rahmen – da regt sich keiner auf!\"  2. Zehn Minuten zu spät – das ist noch drin, da sagt keiner was!  3. Zehn Minuten Verspätung sind ein Tropfen im Ozean – das wirft keine Wellen!"}]'::jsonb, 'Do mochd d''Kotz kaan Buugl!'),
  ('dea-gibd-kaana-schreiadn-kotz-wos', 'Dea gibd kaana schreiadn Kotz wos!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der gibt keiner schreienden Katze was!', '[{"kategorie": "wörtlich", "text": "\"Den erweicht kein Bitten und Betteln!\"  2. \"Den rührt nichts und niemand!\"  3. \"Der sitzt auf seinem Geld wie die Henne auf ihren Eiern!\""}]'::jsonb, 'Den brauchsd goa ned easchd aubeedln - dea gibd kaana schreiadn Kotz wos!'),
  ('den-brauchsd-goa-ned-easchd-aubeedln-dea-gibd-kaana-schreiadn-kotz-wos', 'Den brauchsd goa ned easchd aubeedln - dea gibd kaana schreiadn Kotz wos!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Den brauchst du gar nicht erst anzubetteln - der gibt keiner schreienden Katze was!', '[{"kategorie": "wörtlich", "text": "\"Den kannst du anbetteln bis zum Umfallen – der gibt dir nicht mal Luft zum Atmen!\"  2. Auch wenn du heulst wie ein Schlosshund – der macht keinen Finger krumm!  3. Da kannst du flehen, wie du willst –  der hat die Taschen zugenäht!"}]'::jsonb, ''),
  ('nochn-daabi-haum-se-de-ultras-von-rapid-und-austria-draussd-a-wueuede-kaetscharei-gliifad', 'Nochn Daabi haum se de Ultras von Rapid und Austria draussd a wüüde Kätscharei gliifad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Nach dem Derby haben sich die Ultras von Rapid und Austria draußen eine wilde Catcherei geliefert!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Derby haben sich die Ultras von Rapid und Austria draußen eine wilde Schlägerei geliefert!\"  2. Nach dem Derby lieferten sich die Ultras von Rapid und Austria draußen eine brutale Massenschlägerei!  3. Nach dem Derby entlud sich die Rivalität der Ultras von Rapid und Austria draußen in einer regelrechten Straßenschlacht!"}]'::jsonb, 'Wiina Daabi'),
  ('augfaungan-hod-ollas-mid-an-hoamloosn-kaetschal-owa-aum-schluss-hod-sa-si-zu-aana-wueuesdn-massnschlaegarei-ausgwochsn', 'Augfaungan hod ollas mid an hoamloosn Kätschal, owa aum Schluss hod sa si zu aana wüüsdn Massnschlägarei ausgwochsn!"', '', '', '', 'Wiener Gaunersprache', 'Angefangen hat alles mit einem harmlosen Catcherl - aber am Schluss hat es sich zu einer wüsten Massenschlägerei ausgewachsen!', '[{"kategorie": "wörtlich", "text": "\"Angefangen hat alles mit einer harmlosen Rangelei – aber am Ende wurde daraus eine brutale Massenschlägerei!\"  2. Alles begann mit einem kleinen Handgemenge, doch schließlich eskalierte es zu einer wüsten Massenkeilerei!  3. Aus einem zunächst harmlosen Gerangel entwickelte sich am Schluss eine regelrechte Massenprügelei!"}]'::jsonb, ''),
  ('a-kaetschal-haum', 'a Kätschal haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Catcherl haben', '[{"kategorie": "wörtlich", "text": "\"eine Rauferei haben\";  \"ein Handgemenge austragen\""}, {"kategorie": "", "text": "\"in einen Raufhandel geraten\""}, {"kategorie": "", "text": "\"eine Schlägerei haben\""}]'::jsonb, 'Mit dem wüü I kaa Kätschal haum - dea klopfd di zsaumm wiaran nossn Fetzn!'),
  ('mit-dem-wueue-i-kaa-kaetschal-haum-dea-klopfd-di-zsaumm-wiaran-nossn-fetzn', 'Mit dem wüü I kaa Kätschal haum - dea klopfd di zsaumm wiaran nossn Fetzn!', '', '', '', 'Wiener Gaunersprache', 'Mit dem will ich kein Catcherl haben - der klopft dich zusammen wie einen nassen Fetzen!', '[{"kategorie": "wörtlich", "text": "\"Mit dem will ich keine Schlägerei haben - der klopft dich zusammen wie ein nasses Handtuch!\"  2. Mit dem will ich keine Keilerei – der bügelt dich flach wie ein Hemd!  3. Mit dem fang ich keine Rangelei an – der zerlegt dich in Sekunden!"}]'::jsonb, 'a Kätschal haum'),
  ('da-oide-klapotetz-schaeaewad-lauda-ois-da-traktoa-vom-nochban', 'Da oide Klapotetz schääwad lauda ois da Traktoa vom Nochban!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der alte Klapotetz scheppert lauter als der Traktor vom Nachbarn!', '[{"kategorie": "wörtlich", "text": "\"Der alte Klapotetz rattert schlimmer als der Traktor vom Nachbarn!\"  2. Der alte Klapotetz scheppert, dass dir die Ohren abfallen, ärger als der Traktor vom Nachbarn!  3. Der alte Klapotetz poltert im Takt des Windes noch viel heftiger als der Traktor vom Nachbarn!"}]'::jsonb, ''),
  ('bevua-dea-wos-kneissd-schdeed-vuahea-da-pobst-neem-eam-aum-wiaschdlschdaund', 'Bevua dea wos kneissd, schdeed vuahea da Pobst neem eam aum Wiaschdlschdaund!', '', '', '', 'Wiener Würstelstandjargon', 'Bevor der was kneißt, steht vorher der Papst neben ihm am Würstelstand!', '[{"kategorie": "wörtlich", "text": "\"Bevor der was mitbekommt, steht vorher der Papst neben ihm am Würstelstand!\"  2. Bevor der was checkt, schneit’s im Juli auf der Donauinsel!  3. Bevor der was kapiert, ist der Mond schon dreimal aufgegangen!"}]'::jsonb, ''),
  ('bevua-dea-wos-gneissd-schdeed-vuahea-da-pobst-neem-eam-aum-wiaschdlschdaund', 'Bevua dea wos gneissd, schdeed vuahea da Pobst neem eam aum Wiaschdlschdaund!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bevor der was gneißt, steht vorher der Papst neben ihm am Würstelstand!', '[{"kategorie": "wörtlich", "text": "\"Bevor der was mitbekommt, steht vorher der Papst neben ihm am Würstelstand!\"  2. Bevor der was checkt, schneit’s im Juli auf der Donauinsel!  3. Bevor der was kapiert, ist der Mond schon dreimal aufgegangen!"}]'::jsonb, ''),
  ('nuara-kneissa-wia-du-duachschaud-so-an-schmaeae', 'Nuara Kneissa wia du duachschaud so an Schmää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nur ein Kneißer wie du durchschaut so einen Schmäh!', '[{"kategorie": "wörtlich", "text": "\"Nur ein Checker wie du durchschaut so einen Schwindel!\"  2. Nur ein helles Köpfchen wie du checkt so einen Trick!  3. Nur ein pfiffiger Hund wie du durchblickt so ein Spielchen!"}]'::jsonb, ''),
  ('nuara-gneissa-wia-du-duachschaud-so-an-schmaeae', 'Nuara Gneissa wia du duachschaud so an Schmää!', '', '', '', 'Wiener Kartentipplerjargon', 'Nur ein Gneißer wie du durchschaut so einen Schmäh!', '[{"kategorie": "wörtlich", "text": "\"Nur ein Checker wie du durchschaut so einen Schwindel!\"  2. Nur ein helles Köpfchen wie du checkt so einen Trick!  3. Nur ein pfiffiger Hund wie du durchblickt so ein Spielchen!"}]'::jsonb, ''),
  ('nooch-zwa-bia-auf-niachtanan-moong-woara-scho-kniawaach', 'Nooch zwa Bia auf niachtanan Moong woara scho kniawaach!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nach zwei Bier auf nüchternen Magen war er schon knieweich!', '[{"kategorie": "wörtlich", "text": "\"Nach zwei Bier auf nüchternen Magen war er schon weich in den Knien!\"  2. Kaum hatte er zwei Bier auf leeren Magen getrunken, war er auch schon wacklig auf den Beinen!  3. Zwei Krügerln Bier auf nüchternen Magen – und er hat sich bewegt wie eine Kuh auf Glatteis!"}]'::jsonb, ''),
  ('nooch-fuenf-sechs-waatschn-woara-kniawaach-wiara-auskochde-nuudl', 'Nooch fünf, sechs Waatschn woara kniawaach wiara auskochde Nuudl!', '', '', '', 'Wiener Gaunersprache', 'Nach fünf, sechs Watschen war er knieweich wie eine ausgekochte Nudel!', '[{"kategorie": "wörtlich", "text": "\"Nach fünf, sechs Watschen war er nur noch ein zitterndes Häufchen Elend!\"  2. Nach fünf, sechs Watschen ging er in die Knie und war weich wie Butter!  3. Nach fünf, sechs Watschen lag er am Boden wie ein Mehlsack!"}]'::jsonb, ''),
  ('vua-an-jeedn-auftritt-wiada-kniawaach-und-neavoes-wiara-klaana-schuibua', 'Vua an jeedn Auftritt wiada kniawaach und neavös wiara klaana Schuibua!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Vor jedem Auftritt wird er knieweich und nervös wie ein kleiner Schulbub!', '[{"kategorie": "wörtlich", "text": "\"Vor jedem Auftritt wird er weich in den Knien und zittert wie ein kleiner Schuljunge!\"  2. Vor jedem Auftritt wird er unsicher auf den Beinen und nervös wie ein Anfänger!  3. Vor jedem Auftritt bekommt er weiche Knie und flatternde Nerven!"}]'::jsonb, ''),
  ('sei-so-kniawaach-und-kumm-ma-a-bissl-entgeeng', 'Sei so kniawaach und kumm ma a bissl entgeeng!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sei so knieweich und komm mir ein bisschen entgegen!', '[{"kategorie": "wörtlich", "text": "\"Sei so gütig und komm mir ein Stück entgegen!\"  2. Sei so nett und komm mir bitte auf halbem Weg entgegen!  3. Sei so entgegenkommend und gib ein Stück nach!"}]'::jsonb, ''),
  ('des-is-a-kniawaacha-dillo', 'Des is a kniawaacha Dillo!', '', '', '', 'Wiener Gaunersprache', 'Das ist ein knieweicher Dillo!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Schlappschwanz, der gleich in die Knie geht!\"  2. \"Das ist ein Hosenscheißer ohne jedes Rückgrat!\"  3. \"Das ist ein Warmduscher, der einknickt ein wie ein schlapper Fetzen!\""}]'::jsonb, ''),
  ('jodln-tuan-de-gscheadn-wia-weana-duudln', 'Jodln tuan de Gscheadn, wia Weana duudln!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Jodeln tun die Gescherten, wir Wiener dudeln!', '[{"kategorie": "wörtlich", "text": "\"Jodeln tun die Landler, wir Wiener dudeln!\"  2. In den Alpen wird gejodelt, wir Wiener aber dudeln"}, {"kategorie": "", "text": "Auf’m Land wird gejodelt, in Wien aber wird charmant gedudelt!"}]'::jsonb, ''),
  ('von-an-most-kriagst-kaan-duudla', 'Von an Most kriagst kaan Duudla!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Von einem Most kriegst du keinen Dudler', '[{"kategorie": "wörtlich", "text": "\"Von einem vergorenen Traubensaft bekommst du keinen Rausch!\"  2. Von ein bisschen Traubensaft wirst du nicht betrunken!  3. in Gläschen vergorener Trauben macht noch keinen Rausch!"}]'::jsonb, ''),
  ('si-hod-an-duudla-ausselossn-dea-mei-heaz-zum-schmoeoezn-brochd-hod', 'Si hod an Duudla ausselossn, dea mei Heaz zum Schmöözn brochd hod!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Sie hat einen Dudler rausgelassen, der mein Herz zum Schmelzen gebracht hat!', '[{"kategorie": "wörtlich", "text": "\"Sie hat einen wienerischen Jodler von sich gegeben, der mein Herz zum Schmelzen gebracht hat!\"  2. Sie hat einen Wiener Dudler angestimmt, der mir direkt ins Herz gegangen ist!  3. Ihr wienerischer Dudler hat mein Herz dahinschmelzen lassen!"}]'::jsonb, ''),
  ('de-heisldackn-faeud-ois-haedad-aana-driiwagwiischald', 'De Heisldackn fäud, ois hädad aana driiwagwiischald!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Klodacken fäult, als hätte jemand drübergewischerlt!', '[{"kategorie": "wörtlich", "text": "\"Die WC-Matte stinkt, als hätte jemand draufgepinkelt!\"  2. Der Toilettenvorleger stinkt nach öffentlichem Pissoir!  3. Die Pinkelmatte riecht wieder mal so, als hätt'' einer drübergeschifft!"}]'::jsonb, ''),
  ('waunnsd-de-heisldackn-hinta-da-schaunk-siichsd-vageed-da-glei-da-appetit', 'Waunnsd de Heisldackn hinta da Schaunk siichsd, vageed da glei da Appetit!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du die Klodacken hinter der Schank siehst, vergeht dir gleich der Appetit!', '[{"kategorie": "wörtlich", "text": "\"Beim Anblick der ranzigen Alten hinter dem Tresen vergeht dir gleich der Appetit!\"  2. Wenn du die Schabracke hinter der Schank stehen siehst, vergeht dir sofort der Hunger!  3. Sobald du die unansehnliche Alte hinter der Schank erblickst, vergeht dir im Nu der Appetit!"}]'::jsonb, ''),
  ('de-oide-heisldackn-schdeed-no-imma-am-proodaschdrich-dabei-draad-si-ned-amoi-mea-a-hund-nooch-dera-um', 'De oide Heisldackn schdeed no imma am Proodaschdrich, dabei draad si ned amoi mea a Hund nooch dera um!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die alte Klodacken steht noch immer am Praterstrich, dabei dreht sich nicht einmal mehr ein Hund nach der um!', '[{"kategorie": "wörtlich", "text": "\"Die alte Hure steht noch immer am Praterstrich, dabei dreht sich nicht einmal mehr ein Hund nach ihr um!\"  2. Die abgehalfterte Hure vom Praterstrich schafft noch immer an, dabei will kaum noch ein Freier was von ihr!  3. Die ausgediente Strichkatze tigert noch immer am Praterstrich herum, dabei findet sie kaum noch Kundschaft!"}]'::jsonb, ''),
  ('de-kloodackn-faeud-ois-haedad-aana-driiwagwiischald', 'De Kloodackn fäud, ois hädad aana driiwagwiischald!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Klodacken fäult, als hätte jemand drübergewischerlt!', '[{"kategorie": "wörtlich", "text": "\"Die WC-Matte stinkt, als hätte jemand draufgepinkelt!\"  2. Der Toilettenvorleger stinkt nach öffentlichem Pissoir!  3. Die Pinkelmatte riecht wieder mal so, als hätt'' einer drübergeschifft!"}]'::jsonb, ''),
  ('waunnsd-de-kloodackn-hinta-da-schaunk-siichsd-vageed-da-glei-da-appetit', 'Waunnsd de Kloodackn hinta da Schaunk siichsd, vageed da glei da Appetit!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn du die Klodacken hinter der Schank siehst, vergeht dir gleich der Appetit!', '[{"kategorie": "wörtlich", "text": "\"Beim Anblick der ranzigen Alten hinter dem Tresen vergeht dir gleich der Appetit!\"  2. Wenn du die Schabracke hinter der Schank stehen siehst, vergeht dir sofort der Hunger!  3. Sobald du die unansehnliche Alte hinter der Schank erblickst, vergeht dir im Nu der Appetit!"}]'::jsonb, ''),
  ('de-oide-kloodackn-schdeed-no-imma-am-proodaschdrich-dabei-draad-si-ned-amoi-mea-a-hund-nooch-dera-um', 'De oide Kloodackn schdeed no imma am Proodaschdrich, dabei draad si ned amoi mea a Hund nooch dera um!', '', '', '', 'Wiener Gaunersprache', 'Die alte Klodacken steht noch immer am Praterstrich, dabei dreht sich nicht einmal mehr ein Hund nach der um!', '[{"kategorie": "wörtlich", "text": "\"Die alte Hure steht noch immer am Praterstrich, dabei dreht sich nicht einmal mehr ein Hund nach ihr um!\"  2. Die abgehalfterte Hure vom Praterstrich schafft noch immer an, dabei will kaum noch ein Freier was von ihr!  3. Die ausgediente Strichkatze tigert noch immer am Praterstrich herum, dabei findet sie kaum noch Kundschaft!"}]'::jsonb, ''),
  ('dea-hod-sei-fettn-in-da-kloomuschl-ausgschloofn', 'Dea hod sei Fettn in da Kloomuschl ausgschloofn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der hat seine Fetten in der Klomuschel ausgeschlafen!', '[{"kategorie": "wörtlich", "text": "\"Der hat seinen Rausch in der Klomuschel ausgeschlafen!\"  2. Der hat seinen Rausch in der Toilettenschüssel ausgeschlafen!  3. Der hat seinen Rausch in der Kotzschüssel ausgeschlafen!"}]'::jsonb, ''),
  ('da-oide-koowara-schiabd-seine-zoodln-wia-schachfiguan-aum-schdrich-umanaund', 'Da oide Koowara schiabd seine Zoodln wia Schachfiguan aum Schdrich umanaund!', '', '', '', 'Wiener Gaunersprache', 'Der alte Koberer schiebt seine Zotteln wie Schachfiguren am Strich herum!', '[{"kategorie": "wörtlich", "text": "\"Der alte Zuhälter schiebt seine Huren wie Schachfiguren am Strich herum!\"  2. Der alte Kuppler positioniert seine Prostituierten am Strich wie Figuren auf einem Schachbrett!  3. Der alte Puffvater verschiebt seine Frauen am Strich wie Schachfiguren!"}]'::jsonb, ''),
  ('jeeda-gauna-brauchd-an-koowara-bei-dema-zua-not-a-poa-toog-laung-heimlich-ootauchn-kau', 'Jeeda Gauna brauchd an Koowara, bei dema zua Not a poa Toog laung heimlich ootauchn kau!', '', '', '', 'Wiener Gaunersprache', 'Jeder Gauner braucht einen Koberer, bei dem er zur Not ein paar Tage lang heimlich abtauchen kann!', '[{"kategorie": "wörtlich", "text": "\"Jeder Gauner braucht einen verlässlichen Freund, bei dem er zur Not ein paar Tage lang unangemeldet wohnen kann!\"  2. Jeder Gauner braucht einen befreundeten Herbergsgeber, der ihm im Ernstfall Schutz und Unterschlupf gewährt!  3. Jeder Gauner braucht einen Freund im Dunkeln, bei dem er für ein paar Tage abtauchen kann!"}]'::jsonb, ''),
  ('obsd-aum-fensta-koowasd-oda-auf-da-schdrossn-mochd-an-groossn-untaschiid', 'Obsd aum Fensta koowasd oda auf da Schdrossn, mochd an groossn Untaschiid!', '', '', '', 'Wiener Gaunersprache', 'Ob du am Fenster koberst oder auf der Straße, macht einen großen Unterschied!', '[{"kategorie": "wörtlich", "text": "\"Ob du am Fenster oder auf der Straße Kundschaft köderst, macht einen großen Unterschied!\"  2. Ob du am Fenster anschaffst oder draußen auf der Straße, das ist ein Riesenunterschied!  3. Ob du dich am Fenster feilbietest oder unten auf dem Strich stehst, macht einen großen Unterschied!"}]'::jsonb, ''),
  ('de-maadln-sitzn-in-da-ausloog-und-koowan-duachs-fenstaglaasl-zoolungskraeftige-freia-au', 'De Maadln sitzn in da Ausloog und koowan duachs Fenstaglaasl zoolungskräftige Freia au!', '', '', '', 'Wiener Gaunersprache', 'Die Mädchen sitzen in der Auslage und kobern durchs Fensterglas zahlungskräftige Freier an!', '[{"kategorie": "wörtlich", "text": "\"Die Mädchen sitzen in der Auslage und werben durchs Fensterglas um zahlungskräftige Freier!\"  2. Die Mädchen sitzen in der Auslage und locken zahlungskräftige Freier mit Blicken durchs Fensterglas an!  3. Die Strichmädchen sitzen hinter der Scheibe und keilen zahlungskräftige Freier durchs Fenster an!"}]'::jsonb, ''),
  ('wem-koid-woam-geem', 'wem koid-woam geem', '', '', '', 'Grundwortschatz Wienerisch', 'jemandem kalt-warm geben', '[{"kategorie": "wörtlich", "text": "\"jemanden heiß und kalt machen\""}, {"kategorie": "allg.", "text": "\"jemanden zappeln lassen\" (jemandem gleichzeitig Zuneigung und Distanz zeigen), \"jemandem mal die kalte und dann die warme Schulter zeigen\", \"ein Spiel mit jemandem spielen\""}, {"kategorie": "fig., Gaunersprache", "text": "\"jemandem Feuer unter dem Hintern machen\", \"jemandem die Hölle heißmachen\", \"jemandem die Hölle auf Erden bereiten\""}]'::jsonb, 'Dem wear I koid-woam geem!')
